INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.IDIOMS_FIXED', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI', 'english', 6, 'Know idioms and fixed phrases', ARRAY['ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.c', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.c', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.b', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.c', 'ENGL.G6.WRITIN.T8_CREATIVE_WRITING.b']::text[], 'Gives the meaning of idioms and fixed phrases (work like a dog, dog tired, burst into tears, a piece of cake, under the weather), completes them with the right word, and does not read them word for word, in 8 of 10 new items.', '["choose the meaning","fill the gap","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.CHILD_LABOUR_WORDS', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI', 'english', 6, 'Use words about child labour and child rights', ARRAY['ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.b']::text[], 'Chooses the right word from the theme (employ, exploit, labour, wages, trafficking, abuse, rescue, protect) to complete a sentence, and does not mix a person with an action, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.MAIN_IDEA', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI', 'english', 6, 'Find the main idea and specific details of a text', ARRAY['ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.d', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.b', 'ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.a', 'ENGL.G6.LISTEN.T11_PRONUNCIATION_AND_VO.c']::text[], 'Chooses the sentence or title that covers the whole text, tells it from a detail, and finds a specific detail asked for, in 8 of 10 new texts.', '["choose the main idea","choose the best title","find the specific detail"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'ENGL.G6.READIN.T1_EXTENSIVE_READING', 'english', 6, 'Use reference materials: dictionary, atlas, index and contents', ARRAY['ENGL.G6.READIN.T1_EXTENSIVE_READING.c']::text[], 'Chooses the right reference for a need, puts words in alphabetical order beyond the first letter, and decides from guide words whether a word is on a page, in 8 of 10 new items.', '["choose the correct book","put words in alphabetical order","decide from guide words"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.SUITABLE_TEXT', 'ENGL.G6.READIN.T1_EXTENSIVE_READING', 'english', 6, 'Judge whether a book or text suits a purpose', ARRAY['ENGL.G6.READIN.T1_EXTENSIVE_READING.a', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.d', 'ENGL.G6.READIN.T5_EXTENSIVE_READING.a', 'ENGL.G6.READIN.T5_EXTENSIVE_READING.c', 'ENGL.G6.READIN.T7_EXTENSIVE_READING.a', 'ENGL.G6.READIN.T13_EXTENSIVE_READING.a', 'ENGL.G6.READIN.T8_FLUENCY.a']::text[], 'Chooses the book or text that fits a reader''s purpose, level and interest (information, enjoyment, a topic), and does not choose by the cover, the length or the title alone, in 8 of 10 new items.', '["choose the book for a purpose","judge the relevance of a text"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.INDEPENDENT_READING', 'ENGL.G6.READIN.T1_EXTENSIVE_READING', 'english', 6, 'Read a variety of texts independently', ARRAY['ENGL.G6.READIN.T1_EXTENSIVE_READING.b', 'ENGL.G6.READIN.T5_EXTENSIVE_READING.b', 'ENGL.G6.READIN.T7_EXTENSIVE_READING.b', 'ENGL.G6.READIN.T13_EXTENSIVE_READING.b']::text[], 'The child reads fiction, non-fiction, poems and digital texts alone each week, keeps a reading log and can say what each was about and whether it was worth reading. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["reading log","book talk","retell to a partner"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T1_WORD_CLASSES.DETERMINERS', 'ENGL.G6.LANGUA.T1_WORD_CLASSES', 'english', 6, 'Use some, enough, each and a lot of', ARRAY['ENGL.G6.LANGUA.T1_WORD_CLASSES.a', 'ENGL.G6.LANGUA.T1_WORD_CLASSES.b', 'ENGL.G6.LANGUA.T1_WORD_CLASSES.c']::text[], 'Chooses some, enough, each or a lot of to fit the noun and the verb (each takes a singular noun and verb, a lot of takes plural or uncountable, some in an offer or a statement), and does not write each of the boys are or a lots of, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS', 'ENGL.G6.WRITIN.T1_GUIDED_WRITING', 'english', 6, 'Fill in and plan a form', ARRAY['ENGL.G6.WRITIN.T1_GUIDED_WRITING.a', 'ENGL.G6.WRITIN.T1_GUIDED_WRITING.b']::text[], 'Puts each detail in the field it belongs to (surname, date of birth, signature), follows the form''s own instruction (block letters, tick one, write N/A), and says which fields a form needs for its purpose, in 8 of 10 new items.', '["choose the entry for a field","choose the field a form needs"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.PROVERBS_USE', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI', 'english', 6, 'Know proverbs and use them', ARRAY['ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.a', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.c', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.c', 'ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.c', 'ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.b', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.c']::text[], 'Matches a proverb to its meaning, finishes it with the right word and picks the situation it fits, and does not read it word for word, in 8 of 10 new items.', '["choose the meaning","finish the proverb","choose the situation"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.SIMILE_METAPHOR', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI', 'english', 6, 'Tell similes from metaphors and complete them', ARRAY['ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.c', 'ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.c', 'ENGL.G6.LISTEN.T7_PRONUNCIATION_AND_IN.d', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.c', 'ENGL.G6.WRITIN.T6_CREATIVE_WRITING.b']::text[], 'Says that a simile compares with like or as and a metaphor says one thing is another, completes familiar similes (as hungry as a wolf), and does not write as ... like, in 8 of 10 new items.', '["simile or metaphor","fill the gap","choose the correct word"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'ENGL.G6.READIN.T2_INTENSIVE_READING', 'english', 6, 'Name characters, places and events and put events in order', ARRAY['ENGL.G6.READIN.T2_INTENSIVE_READING.a']::text[], 'Names the characters and the places in a short story, and puts four of its events in the order they happened, in 8 of 10 new passages.', '["short comprehension: choose","short comprehension: type","put the events in order"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.PREDICT', 'ENGL.G6.READIN.T2_INTENSIVE_READING', 'english', 6, 'Predict what happens next', ARRAY['ENGL.G6.READIN.T2_INTENSIVE_READING.b']::text[], 'Uses clues in the story to choose the most likely next event and says which clue supports it, in 8 of 10 new passages.', '["choose the best prediction","choose the clue that supports it"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'ENGL.G6.READIN.T2_INTENSIVE_READING', 'english', 6, 'Answer factual questions from a text', ARRAY['ENGL.G6.READIN.T2_INTENSIVE_READING.c', 'ENGL.G6.READIN.T3_INTENSIVE_READING.b', 'ENGL.G6.READIN.T4_INTENSIVE_READING.c', 'ENGL.G6.READIN.T6_INTENSIVE_READING.c', 'ENGL.G6.READIN.T9_INTENSIVE_READING_FI.c', 'ENGL.G6.READIN.T10_INTENSIVE_READING.b', 'ENGL.G6.READIN.T11_INTENSIVE_READING_DI.c', 'ENGL.G6.READIN.T12_INTENSIVE_READING.c']::text[], 'Finds an answer that is stated in the text, tells true from false and not stated, and does not pick a detail that sits near the answer, in 8 of 10 new passages.', '["short comprehension: choose","true, false or not stated","short comprehension: type"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'ENGL.G6.READIN.T2_INTENSIVE_READING', 'english', 6, 'Answer inferential questions from a text', ARRAY['ENGL.G6.READIN.T2_INTENSIVE_READING.c', 'ENGL.G6.READIN.T3_INTENSIVE_READING.b', 'ENGL.G6.READIN.T4_INTENSIVE_READING.c', 'ENGL.G6.READIN.T6_INTENSIVE_READING.c', 'ENGL.G6.READIN.T9_INTENSIVE_READING_FI.c', 'ENGL.G6.READIN.T10_INTENSIVE_READING.b', 'ENGL.G6.READIN.T11_INTENSIVE_READING_DI.c', 'ENGL.G6.READIN.T12_INTENSIVE_READING.c']::text[], 'Works out what the text does not say outright (why a character acts, how they feel) and does not give an answer the text contradicts or merely repeats, in 8 of 10 new passages.', '["short comprehension: choose","stated or worked out"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.IMAGERY', 'ENGL.G6.READIN.T2_INTENSIVE_READING', 'english', 6, 'Create mental images from a poem or story', ARRAY['ENGL.G6.READIN.T2_INTENSIVE_READING.d', 'ENGL.G6.READIN.T9_INTENSIVE_READING_FI.b', 'ENGL.G6.READIN.T11_INTENSIVE_READING_DI.b', 'ENGL.G6.READIN.T4_INTENSIVE_READING.b']::text[], 'Picks the words of a poem or story that make a picture, and says what the writer wants the reader to see, hear or feel, and does not pick the line that only gives a fact, in 8 of 10 new items.', '["choose the line that paints a picture","choose what the picture shows"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.CHARACTER_JUDGE', 'ENGL.G6.READIN.T2_INTENSIVE_READING', 'english', 6, 'Judge a character from what they say and do', ARRAY['ENGL.G6.READIN.T2_INTENSIVE_READING.e']::text[], 'Chooses the trait that the character''s words and actions support (kind, selfish, brave, honest), and says which line is the evidence, and does not judge from the name or one word, in 8 of 10 new items.', '["choose the trait","choose the evidence"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T2_WORD_CLASSES.CONCRETE_ABSTRACT', 'ENGL.G6.LANGUA.T2_WORD_CLASSES', 'english', 6, 'Tell concrete and abstract nouns apart and use them', ARRAY['ENGL.G6.LANGUA.T2_WORD_CLASSES.a', 'ENGL.G6.LANGUA.T2_WORD_CLASSES.b']::text[], 'Names nouns we can see or touch as concrete (mango, river) and nouns for ideas, feelings and qualities as abstract (honesty, hunger, bravery), and writes the noun form (honesty, not honest) in a gap, in 8 of 10 new items.', '["pick the abstract noun","pick the concrete noun","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PARAGRAPH_ORDER', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING', 'english', 6, 'Build a paragraph: topic sentence, order and the sentence that does not belong', ARRAY['ENGL.G6.WRITIN.T2_CREATIVE_WRITING.b', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.d', 'ENGL.G6.WRITIN.T5_CREATIVE_WRITING.b']::text[], 'Chooses the sentence that opens a paragraph, puts supporting sentences in a logical order and finds the sentence that does not belong, in 8 of 10 new paragraphs.', '["choose the topic sentence","find the sentence that does not belong","put the sentences in order"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PLAN_COMPOSITION', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING', 'english', 6, 'Plan a composition: choose a topic, gather and order ideas', ARRAY['ENGL.G6.WRITIN.T2_CREATIVE_WRITING.a', 'ENGL.G6.WRITIN.T5_CREATIVE_WRITING.a', 'ENGL.G6.WRITIN.T6_CREATIVE_WRITING.a', 'ENGL.G6.WRITIN.T8_CREATIVE_WRITING.a']::text[], 'Before writing, the child chooses a topic, lists ideas that keep to it, drops the ones that do not and orders the rest into an introduction, body and conclusion. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which idea fits the topic","order the plan","which topic suits these pictures"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING', 'english', 6, 'Write an open-ended composition on a variety of themes', ARRAY['ENGL.G6.WRITIN.T2_CREATIVE_WRITING.c']::text[], 'The child writes a composition from a plan in clear paragraphs, with each idea on topic, varied linking words and some vivid language. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write about","write from your plan","continue the composition"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_TALK', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO', 'english', 6, 'Use polite expressions: the telephone, interrupting and asking for clarification', ARRAY['ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.b', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.d', 'ENGL.G6.LISTEN.T7_PRONUNCIATION_AND_IN.c', 'ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.b', 'ENGL.G6.LISTEN.T7_PRONUNCIATION_AND_IN.b', 'ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.e']::text[], 'Chooses the polite way to answer a call, to take a message, to interrupt (Excuse me, may I add something?) and to ask for clarification (Could you say that again, please?), and spots a rude or blunt turn, in 8 of 10 new items.', '["choose the polite expression","fill the gap","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO', 'english', 6, 'Pronounce the target sounds correctly in words and phrases', ARRAY['ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.a', 'ENGL.G6.LISTEN.T7_PRONUNCIATION_AND_IN.a', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.b']::text[], 'The child says the Grade 6 target sounds (/ʊə/ as in tour, /f/ and /v/, /əʊ/ as in phone, /h/) so that a listener hears the right word: tour not tore, van not fan, phone not fon, hat not at. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say the word after the teacher","read the pairs aloud","say a tongue twister"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T3_INTENSIVE_READING.CONTEXT_CLUES', 'ENGL.G6.READIN.T3_INTENSIVE_READING', 'english', 6, 'Use context clues to find the meaning of words, proverbs and similes', ARRAY['ENGL.G6.READIN.T3_INTENSIVE_READING.c', 'ENGL.G6.READIN.T6_INTENSIVE_READING.b', 'ENGL.G6.READIN.T10_INTENSIVE_READING.c', 'ENGL.G6.READIN.T3_INTENSIVE_READING.a', 'ENGL.G6.READIN.T11_INTENSIVE_READING_DI.a']::text[], 'Uses the words around an unfamiliar word, proverb or simile to choose its meaning and says which words gave the clue, in 8 of 10 new passages.', '["short comprehension: choose","choose the clue words"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.CORRELATIVE', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT', 'english', 6, 'Use both ... and, either ... or, neither ... nor and not only ... but also', ARRAY['ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.a', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.b', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.d']::text[], 'Pairs the two halves correctly (both with and, either with or, neither with nor, not only with but also), keeps the verb singular or plural to match, and writes no extra not after neither, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.SHOW_PATTERN', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT', 'english', 6, 'Use show or tell me + how, where or who in a sentence', ARRAY['ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.c', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.d']::text[], 'Writes the question word, then the subject, then the verb (Show me where the library is), without turning the verb round as in a question, in 8 of 10 new sentences.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.ABBREVIATIONS', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING', 'english', 6, 'Use common abbreviations and acronyms', ARRAY['ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.a', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.d']::text[], 'Writes and reads the short form of common titles and words (Mr, Dr, etc.), expands Kenyan acronyms (KNEC, KWS, KRA), and tells an abbreviation from an acronym (an acronym is said as a word, like UNICEF), in 8 of 10 new items.', '["choose the short form","choose the full form","tell an acronym from an abbreviation"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.NUMERALS', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING', 'english', 6, 'Write numbers in words and figures correctly', ARRAY['ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.a', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.d']::text[], 'Spells numbers in words (forty, fourteen, ninety, eighth), writes ordinals with the right ending (1st, 2nd, 3rd, 4th), and does not begin a sentence with a figure, in 8 of 10 new items.', '["choose the correct spelling","choose the correct sentence","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.RESCUE_WORDS', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO', 'english', 6, 'Use words about emergency and rescue services', ARRAY['ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.b']::text[], 'Chooses the right word (ambulance, paramedic, firefighter, siren, evacuate, first aid, emergency, rescue) for a rescue situation, and does not mix the person, the vehicle and the action, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO', 'english', 6, 'Use stress to tell nouns, verbs and adjectives apart and stress the content words', ARRAY['ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.c', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.d']::text[], 'The child stresses PERmit (noun) and perMIT (verb), OBject and obJECT, and in a sentence stresses the content words (nouns, main verbs, adjectives) and keeps small helping words weak unless they carry the meaning. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say it as a noun and as a verb","which words carry the stress","say the sentence with the right beat"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T4_INTENSIVE_READING.READ_VISUALS', 'ENGL.G6.READIN.T4_INTENSIVE_READING', 'english', 6, 'Predict events from visuals and judge their relevance', ARRAY['ENGL.G6.READIN.T4_INTENSIVE_READING.a', 'ENGL.G6.READIN.T4_INTENSIVE_READING.d']::text[], 'The child uses pictures, diagrams and captions to predict what a text will say, and judges whether a visual matches and helps the text it sits in. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what will happen next","does this picture fit the text","what does the visual show"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T4_WORD_CLASSES.RELATIVE_PRONOUNS', 'ENGL.G6.LANGUA.T4_WORD_CLASSES', 'english', 6, 'Use who, whom, whose and which', ARRAY['ENGL.G6.LANGUA.T4_WORD_CLASSES.a', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.b', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.c']::text[], 'Uses who for a person, which for a thing or animal, whose for belonging, and does not add a second pronoun (the boy who he won), in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T4_WORD_CLASSES.INDEFINITE_PRONOUNS', 'ENGL.G6.LANGUA.T4_WORD_CLASSES', 'english', 6, 'Use someone, anybody, nobody, everything and the like', ARRAY['ENGL.G6.LANGUA.T4_WORD_CLASSES.a', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.b', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.c']::text[], 'Chooses some-, any-, no- or every- with -one, -body or -thing to fit the sentence, uses a singular verb with them, and does not write a double negative (did not see nobody) or noone, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_LETTER', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING', 'english', 6, 'Know the features of a formal letter and invitation', ARRAY['ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.a', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.c']::text[], 'Tells where each part goes (address, date, greeting, subject line, closing, signature), matches the closing to the greeting (Dear Sir with Yours faithfully), and picks the polite formal wording, in 8 of 10 new items.', '["choose the part or its place","choose the formal wording"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_INVITATION', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING', 'english', 6, 'Write a formal invitation letter in the correct format', ARRAY['ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.b']::text[], 'The child writes a formal invitation with the writer''s address, date, the receiver''s address, a formal greeting, a subject line, the event, date, time and place, a polite request to reply, Yours faithfully or Yours sincerely, signature and name. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write an invitation to","correct this invitation","what is missing from the letter"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.ORAL_RESPONSE', 'ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO', 'english', 6, 'Respond to oral questions and listen for specific details', ARRAY['ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.b', 'ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.a']::text[], 'After hearing a short talk about a tourist attraction, the child answers oral questions in full sentences with the details given, and asks one sensible follow-up question. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["answer the question you hear","listen and note the details","ask a follow-up question"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T5_ADJECTIVES.ADJECTIVE_DEGREES', 'ENGL.G6.LANGUA.T5_ADJECTIVES', 'english', 6, 'Use the simple, comparative and superlative forms of adjectives', ARRAY['ENGL.G6.LANGUA.T5_ADJECTIVES.a', 'ENGL.G6.LANGUA.T5_ADJECTIVES.b', 'ENGL.G6.LANGUA.T5_ADJECTIVES.c']::text[], 'Tells the three forms apart and writes as ... as with the simple form, than with the comparative and the with the superlative, and does not write as taller as or the tallest than, in 8 of 10 new items.', '["pick the form","fill the gap","spot the mistake","choose the correct word"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION', 'ENGL.G6.WRITIN.T5_CREATIVE_WRITING', 'english', 6, 'Write and judge a narrative composition', ARRAY['ENGL.G6.WRITIN.T5_CREATIVE_WRITING.c', 'ENGL.G6.WRITIN.T5_CREATIVE_WRITING.d', 'ENGL.G6.WRITIN.T8_CREATIVE_WRITING.c', 'ENGL.G6.WRITIN.T8_CREATIVE_WRITING.d', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.b']::text[], 'The child writes a story with a clear beginning, a problem that builds and an ending, in the past tense, with direct speech punctuated, and judges a story for language, relevance and organisation. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a story about","mark this story with the checklist","improve this story"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO', 'english', 6, 'Choose words by their sound: /ɪə/, /ʊə/, /əʊ/, /f/, /v/ and /h/', ARRAY['ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.a', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.a', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.a', 'ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.a', 'ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.a', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.a', 'ENGL.G6.LISTEN.T11_PRONUNCIATION_AND_VO.a']::text[], 'Picks the word with the same vowel sound as near (/ɪə/), tour (/ʊə/) or go (/əʊ/), or the word that starts with /f/, /v/ or an /h/ that is said (hour and honest start without it), in 8 of 10 new items.', '["pick the word with the same sound","find the odd one out"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.WORK_ETHICS_WORDS', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO', 'english', 6, 'Use words about work and work ethics in sentences', ARRAY['ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.b']::text[], 'The child uses punctual, honest, diligent, integrity, absent, promotion, salary and similar words correctly in sentences about jobs. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the right word","fill the gap","which word fits the worker"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO', 'english', 6, 'Use stress and intonation in questions, statements and exclamations', ARRAY['ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.c']::text[], 'The child uses a falling tune for statements and WH questions, a rising tune for yes or no questions, and a strong, high start for exclamations (What a hard worker!). Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say it as a question, statement and exclamation","up or down at the end","which word is stressed"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T6_INTENSIVE_READING.RELATE_TO_LIFE', 'ENGL.G6.READIN.T6_INTENSIVE_READING', 'english', 6, 'Make connections between events in a text and one''s own experiences', ARRAY['ENGL.G6.READIN.T6_INTENSIVE_READING.a', 'ENGL.G6.READIN.T9_INTENSIVE_READING_FI.a', 'ENGL.G6.READIN.T10_INTENSIVE_READING.a']::text[], 'The child links an event or idea in the text to a real experience or something in the community, says how they are alike and different, and keeps to what the text says. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["has this happened to you","what would you do","how is this like your community"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.PHRASAL_QUANTIFIERS', 'ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS', 'english', 6, 'Use a number of, a great deal of, plenty of and a piece of with the right noun', ARRAY['ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.a', 'ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.b', 'ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.c']::text[], 'Uses a number of and a good many with countable nouns, a great deal of and an amount of with uncountable nouns, and a piece, bottle, loaf or bar of for single items of an uncountable thing, with of every time, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION', 'ENGL.G6.WRITIN.T6_CREATIVE_WRITING', 'english', 6, 'Write and judge a composition from visuals', ARRAY['ENGL.G6.WRITIN.T6_CREATIVE_WRITING.c', 'ENGL.G6.WRITIN.T6_CREATIVE_WRITING.d']::text[], 'The child writes a linked story that covers every picture in order, with names, actions and feelings the pictures suggest, and judges another for relevance, language and creativity. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write the story the pictures tell","give it a title","judge this pictorial composition"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T7_TENSE.FUTURE_CONTINUOUS', 'ENGL.G6.LANGUA.T7_TENSE', 'english', 6, 'Use the future continuous: will be + verb-ing', ARRAY['ENGL.G6.LANGUA.T7_TENSE.a', 'ENGL.G6.LANGUA.T7_TENSE.b', 'ENGL.G6.LANGUA.T7_TENSE.c']::text[], 'Writes will be + verb-ing for an action that will be going on at a stated time (This time tomorrow we will be travelling), and does not write will travelling, will been or a present continuous, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.COMMA_USE', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING', 'english', 6, 'Use the comma', ARRAY['ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.a', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.b', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.c']::text[], 'Puts the comma between items in a list, after an opening word or phrase, round extra information and before or after spoken words, and does not put one between subject and verb or use it to join two sentences, in 8 of 10 new items.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.QUOTATION_MARKS', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING', 'english', 6, 'Use double quotation marks for direct speech', ARRAY['ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.a', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.b', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.c']::text[], 'Puts double quotation marks round the exact words spoken, closes them after the punctuation, keeps the capital letter at the start of the speech and the small letter after said in split speech, and does not use them for reported speech, in 8 of 10 new items.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.RIDDLES_PROVERBS', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO', 'english', 6, 'Tell a riddle from a proverb', ARRAY['ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.a', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.d']::text[], 'Says that a riddle asks a puzzle with a hidden answer and a proverb gives advice or a truth, and answers a simple riddle by what it describes, not by the words in it, in 8 of 10 new items.', '["riddle or proverb","answer the riddle"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.PHRASAL_VERBS_USE', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO', 'english', 6, 'Use phrasal verbs: put up with, cope with, agree with, give up', ARRAY['ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.c', 'ENGL.G6.LISTEN.T11_PRONUNCIATION_AND_VO.b', 'ENGL.G6.WRITIN.T6_CREATIVE_WRITING.b']::text[], 'Chooses the phrasal verb and its particle for a meaning (give up, set off, break down, run out of, put up with, cope with, agree with, look after), and does not use the wrong preposition, in 8 of 10 new items.', '["choose the meaning","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T8_FLUENCY.READ_FLUENTLY', 'ENGL.G6.READIN.T8_FLUENCY', 'english', 6, 'Read a text accurately, at a reasonable speed and with expression', ARRAY['ENGL.G6.READIN.T8_FLUENCY.b', 'ENGL.G6.READIN.T8_FLUENCY.c']::text[], 'The child reads a Grade 6 text aloud at about talking speed, in phrases, with few slips, pausing at punctuation and letting the voice show questions, speech and feeling. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read aloud to the teacher","read the dialogue in parts","reread for expression"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.ACTIVE_PASSIVE', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS', 'english', 6, 'Tell active and passive sentences apart and write the passive', ARRAY['ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.a', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.c', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.d']::text[], 'Says whether the subject does the action (active) or receives it (passive), writes be + the past participle (The window was broken), matches be to the number, and does not leave out be or use the past tense in place of the participle, in 8 of 10 new items.', '["pick the passive sentence","fill the gap","spot the mistake","choose the passive of a sentence"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS', 'english', 6, 'Use say and tell, borrow and lend, bring and take, learn and teach, hear and listen, see and look correctly', ARRAY['ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.b']::text[], 'Chooses between each of these pairs from who is giving, who is receiving and which way the thing moves, and does not use one word for both as in Kiswahili, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.SPEAK_FLUENTLY', 'ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP', 'english', 6, 'Make an oral presentation fluently, accurately and with expression', ARRAY['ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.c', 'ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.b']::text[], 'The child gives a two to three minute talk or speech on a theme from notes, at a steady pace, with few hesitations, clear sounds and expression that fits the message. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["give a short speech","present a talk on the theme","answer questions after the talk"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T9_INTENSIVE_READING_FI.FACT_OPINION', 'ENGL.G6.READIN.T9_INTENSIVE_READING_FI', 'english', 6, 'Tell a fact from an opinion, and a story from information', ARRAY['ENGL.G6.READIN.T9_INTENSIVE_READING_FI.c']::text[], 'Says that a fact can be checked and an opinion says what someone thinks or feels (best, beautiful, should), and tells whether a short text is a made-up story or information, in 8 of 10 new items.', '["choose the fact","choose the opinion","story or information"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T9_ADVERBS.ADVERBS_USE', 'ENGL.G6.LANGUA.T9_ADVERBS', 'english', 6, 'Use adverbs of manner, time, place, frequency and degree', ARRAY['ENGL.G6.LANGUA.T9_ADVERBS.a', 'ENGL.G6.LANGUA.T9_ADVERBS.b', 'ENGL.G6.LANGUA.T9_ADVERBS.c']::text[], 'Tells what an adverb shows, uses well (not good), hard and hardly with their right meanings, puts the adverb of frequency before the main verb (always goes), and does not use an adjective after a verb of action, in 8 of 10 new items.', '["say what the adverb tells us","choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.HYPHENS', 'ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING', 'english', 6, 'Use the hyphen in compound words and numbers', ARRAY['ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.a', 'ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.b', 'ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.c']::text[], 'Writes the hyphen in compound words (well-known, mother-in-law), in numbers from twenty-one to ninety-nine and in a compound before a noun (a ten-year-old boy, but ten years old), and does not write ten-years-old, in 8 of 10 new items.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.EXPRESS_MOODS', 'ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO', 'english', 6, 'Express fitting moods in a conversation', ARRAY['ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.c']::text[], 'The child changes tone, words and face to suit the mood of the conversation (surprised, sorry, pleased, concerned) and does not laugh at sad news or sound angry when pleased. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say it as if you are worried","role play the conversation","show surprise"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T10_CONJUNCTIONS.CONJUNCTIONS_USE', 'ENGL.G6.LANGUA.T10_CONJUNCTIONS', 'english', 6, 'Join ideas with although, unless, while, so that, until and whereas', ARRAY['ENGL.G6.LANGUA.T10_CONJUNCTIONS.a', 'ENGL.G6.LANGUA.T10_CONJUNCTIONS.b', 'ENGL.G6.LANGUA.T10_CONJUNCTIONS.c']::text[], 'Chooses the conjunction that fits the meaning (contrast, condition, purpose, time), uses only one joining word (Although ... but ... is wrong), and does not write unless ... not, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["reasoning","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIBING_WORDS', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING', 'english', 6, 'Use fitting adjectives to describe a person, object or place', ARRAY['ENGL.G6.WRITIN.T10_CREATIVE_WRITING.a']::text[], 'The child chooses exact adjectives for looks, character, size, colour, sound and smell (a towering jacaranda, not a big tree) and puts them in the right order. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the best adjective","improve the description","which adjective fits"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING', 'english', 6, 'Plan, write and judge a descriptive composition', ARRAY['ENGL.G6.WRITIN.T10_CREATIVE_WRITING.b', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING.c', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING.d']::text[], 'The child plans a description by the senses, writes it in a clear order with exact words, and judges a description for language, relevance, creativity and organisation. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["describe a place","plan by the senses","judge this description"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T11_INTERROGATIVES.INTERROGATIVES_USE', 'ENGL.G6.LANGUA.T11_INTERROGATIVES', 'english', 6, 'Ask questions with whose, which, whom, how often, how long and how far', ARRAY['ENGL.G6.LANGUA.T11_INTERROGATIVES.a', 'ENGL.G6.LANGUA.T11_INTERROGATIVES.b', 'ENGL.G6.LANGUA.T11_INTERROGATIVES.c']::text[], 'Chooses the question word that fits the answer given (whose for owner, which for a choice from a set, how often for frequency, how long for time, how far for distance), in 8 of 10 new questions.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING.SYNONYMS_ANTONYMS', 'ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING', 'english', 6, 'Choose synonyms and antonyms', ARRAY['ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING.a', 'ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING.b']::text[], 'Chooses a word with the same meaning (synonym) or the opposite meaning (antonym) in a sentence, and does not give a related word, the same word or the wrong kind of pair, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.NONVERBAL_CUES', 'ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO', 'english', 6, 'Use non-verbal cues to support speech and judge them in others', ARRAY['ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.c', 'ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.d']::text[], 'The child chooses gestures, eye contact and facial expression that support what is said, and judges whether a speaker''s cues in a conversation or video fit the message. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which gesture fits","was this cue right","what does the gesture show"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.READIN.T12_INTENSIVE_READING.POEM_FEATURES', 'ENGL.G6.READIN.T12_INTENSIVE_READING', 'english', 6, 'Find rhyme, repeated lines and rhythm in a poem or song', ARRAY['ENGL.G6.READIN.T12_INTENSIVE_READING.a', 'ENGL.G6.READIN.T12_INTENSIVE_READING.b']::text[], 'Finds the words that rhyme by sound (not by spelling), the line that repeats and the words a poem stresses, in 8 of 10 new poems.', '["choose the rhyming words","choose the repeated line"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE', 'ENGL.G6.LANGUA.T12_QUESTION_TAGS', 'english', 6, 'Form question tags with be, have, do and modal verbs', ARRAY['ENGL.G6.LANGUA.T12_QUESTION_TAGS.a', 'ENGL.G6.LANGUA.T12_QUESTION_TAGS.b', 'ENGL.G6.LANGUA.T12_QUESTION_TAGS.c']::text[], 'Adds the right tag to a statement: the same helper verb with the opposite sign and a pronoun (is/isn''t, has/hasn''t, does/doesn''t, can/can''t, will/won''t), and writes aren''t I after I am, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.JOURNAL', 'ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING', 'english', 6, 'Know the parts of a personal journal entry', ARRAY['ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.a', 'ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.b', 'ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.c']::text[], 'Names what a journal entry has (date, "I", the day''s events in order, feelings) and what it does not (a greeting and a closing as in a letter, "Yours sincerely"), and tells a journal entry from a letter or a news report, in 8 of 10 new items.', '["choose the part a journal has","choose the journal entry"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.MONEY_TRADE_WORDS', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN', 'english', 6, 'Use words about money and trade', ARRAY['ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.a']::text[], 'Chooses the right word (profit, loss, import, export, customer, retailer, wholesaler, wages, budget) for a trading situation, and does not swap the opposite pairs, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.DICTATION', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN', 'english', 6, 'Listen to a short text and write it down accurately', ARRAY['ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.b']::text[], 'The child writes a short text read aloud twice, with every word spelt right, sentence punctuation in place and nothing added or left out. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["write what you hear","check your copy","fill the gaps as you listen"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.LANGUA.T13_WORD_CLASSES.PREPOSITIONS_USE', 'ENGL.G6.LANGUA.T13_WORD_CLASSES', 'english', 6, 'Use between, among, since, for, during, by and the prepositions that follow words', ARRAY['ENGL.G6.LANGUA.T13_WORD_CLASSES.a', 'ENGL.G6.LANGUA.T13_WORD_CLASSES.b', 'ENGL.G6.LANGUA.T13_WORD_CLASSES.c']::text[], 'Chooses between and among, since and for, during and for, by and with, and the preposition a word takes (interested in, afraid of, different from), and does not write interested on or afraid from, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.AFFIXES', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING', 'english', 6, 'Form new words with prefixes and suffixes', ARRAY['ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.a', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.b', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.d']::text[], 'Chooses the prefix (un-, dis-, mis-, re-, in-, im-) or suffix (-ful, -less, -ness, -ment, -able) that makes the meaning wanted, and keeps the spelling right (happy to happiness, care to careful), in 8 of 10 new items.', '["choose the word part","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.SPELLING_RULES', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING', 'english', 6, 'Spell words correctly: ie and ei, silent letters, double letters', ARRAY['ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.c']::text[], 'Spells words that often go wrong (receive, believe, separate, necessary, government, environment, tomorrow, library, February) from the sound, the rule or the picture of the word, in 8 of 10 new words.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
