INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.IDIOMS_FIXED.M_IDM_LITERAL', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.IDIOMS_FIXED', 'Reads an idiom word for word.', '{"question":"What does \"dog tired\" mean?","wrong_answer":"tired like a dog","correct_answer":"very, very tired"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "tired like a dog" next to the right answer in a new sentence and ask again.', 'An idiom''s meaning is not the sum of its words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.IDIOMS_FIXED.M_IDM_WORD_CHANGED', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.IDIOMS_FIXED', 'Changes a word of the idiom (work like a cat).', '{"question":"He had to work like a ___ all day.","wrong_answer":"cat","correct_answer":"dog"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "cat" next to the right answer in a new sentence and ask again.', 'An idiom is fixed. Change one word and it is lost.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.IDIOMS_FIXED.M_IDM_OPPOSITE', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.IDIOMS_FIXED', 'Takes the opposite meaning of an idiom.', '{"question":"What does \"a piece of cake\" mean?","wrong_answer":"very difficult","correct_answer":"very easy"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "very difficult" next to the right answer in a new sentence and ask again.', 'Ask what the picture suggests: cake is easy to eat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.IDIOMS_FIXED.M_IDM_WRONG_SITUATION', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.IDIOMS_FIXED', 'Uses an idiom in a situation it does not fit.', '{"question":"When would you say \"burst into tears\"?","wrong_answer":"when you are very happy","correct_answer":"when you suddenly cry"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "when you are very happy" next to the right answer in a new sentence and ask again.', 'Match the idiom to the feeling or the event.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.CHILD_LABOUR_WORDS.M_CL_PERSON_ACTION', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.CHILD_LABOUR_WORDS', 'Uses a word for the person where the action is needed (employer for employ).', '{"question":"It is against the law to ___ young children to work.","wrong_answer":"employer","correct_answer":"employ"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "employer" next to the right answer in a new sentence and ask again.', 'Employ is the action. The employer is the person who does it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.CHILD_LABOUR_WORDS.M_CL_EXPLOIT_HELP', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.CHILD_LABOUR_WORDS', 'Takes a harsh word for a kind one (exploit for protect).', '{"question":"The law is there to ___ children from harm.","wrong_answer":"exploit","correct_answer":"protect"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "exploit" next to the right answer in a new sentence and ask again.', 'Exploit means to use someone unfairly. Protect means to keep safe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.CHILD_LABOUR_WORDS.M_CL_WAGES_FEES', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.CHILD_LABOUR_WORDS', 'Mixes wages (pay for work) with fees (pay for a service).', '{"question":"The boy was paid very low ___ for a full day of hard work.","wrong_answer":"fees","correct_answer":"wages"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "fees" next to the right answer in a new sentence and ask again.', 'Wages: money paid for work. Fees: money you pay for school or a service.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.MAIN_IDEA.M6_MAIN_DETAIL', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.MAIN_IDEA', 'Picks a detail as the main idea.', '{"question":"What is the main idea?","wrong_answer":"a detail","correct_answer":"what the whole passage is about"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a detail" next to the right answer in a new sentence and ask again.', 'The main idea covers all of the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.MAIN_IDEA.M6_MAIN_TOO_BROAD', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.MAIN_IDEA', 'Picks an idea that is wider than the passage.', '{"question":"What is the main idea?","wrong_answer":"a very general statement","correct_answer":"what the passage is about"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a very general statement" next to the right answer in a new sentence and ask again.', 'The main idea fits this passage, not every passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.MAIN_IDEA.M6_MAIN_NOT_IN_TEXT', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.MAIN_IDEA', 'Picks an idea that is not in the passage.', '{"question":"What is the main idea?","wrong_answer":"something not in the text","correct_answer":"what the passage says"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "something not in the text" next to the right answer in a new sentence and ask again.', 'Check the idea against the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.MAIN_IDEA.M_MAIN_DETAIL_FOR_ASKED', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.MAIN_IDEA', 'Gives the main idea when a specific detail is asked, or the reverse.', '{"question":"What time did the bus leave?","wrong_answer":"it left late","correct_answer":"at half past six"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "it left late" next to the right answer in a new sentence and ask again.', 'A detail question asks for one fact, like a time or a name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.CHILD_LABOUR_WORDS.M6_CL_CHORE_LABOUR', 'ENGL.G6.LISTEN.T1_PRONUNCIATION_AND_LI.CHILD_LABOUR_WORDS', 'Calls every household chore child labour.', '{"question":"A girl washes her own plate after supper. This is ...","wrong_answer":"child labour","correct_answer":"a fair responsibility"}'::jsonb, 'Child labour is learnt as "any work by a child".', 'Offer "child labour" beside "a fair responsibility" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Child labour is harmful work that stops a child learning or hurts her.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M_REF_WRONG_BOOK', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Chooses the wrong reference book.', '{"question":"Which book helps you find a country on the map?","wrong_answer":"dictionary","correct_answer":"atlas"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "dictionary" next to the right answer in a new sentence and ask again.', 'Dictionary: words. Atlas: maps. Encyclopaedia: facts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M_REF_ALPHA_FIRST', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Orders words by first letter only.', '{"question":"Put in alphabetical order: bread, brave, brick.","wrong_answer":"bread, brave, brick","correct_answer":"brave, bread, brick"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "bread, brave, brick" next to the right answer in a new sentence and ask again.', 'When the first letters match, look at the next letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M6_REF_GUIDE_WORDS', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Misreads guide words.', '{"question":"Guide words are \"farm\" and \"feast\". Which word is on the page?","wrong_answer":"fence","correct_answer":"fast"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "fence" next to the right answer in a new sentence and ask again.', 'The word must come after the first guide and before the last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M_REF_INDEX_CONTENTS', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Uses the contents page when the index is needed or the reverse.', '{"question":"Which part of a book lists the page for one small topic?","wrong_answer":"contents","correct_answer":"index"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "contents" next to the right answer in a new sentence and ask again.', 'Contents: chapters in order. Index: every topic in A to Z.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.SUITABLE_TEXT.M_TXT_WRONG_GENRE', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.SUITABLE_TEXT', 'Chooses a story to find facts or a fact book for enjoyment.', '{"question":"Which book would help you learn how bees make honey?","wrong_answer":"a story about a bee","correct_answer":"an information book about bees"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a story about a bee" next to the right answer in a new sentence and ask again.', 'Information: facts. Story: enjoyment.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.SUITABLE_TEXT.M_TXT_COVER_ONLY', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.SUITABLE_TEXT', 'Judges a book by its cover or its size.', '{"question":"What is the best way to judge if a book suits you?","wrong_answer":"look at the cover only","correct_answer":"read the blurb and a page"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "look at the cover only" next to the right answer in a new sentence and ask again.', 'The blurb and a page show the topic and the level.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.SUITABLE_TEXT.M_TXT_TOO_HARD', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.SUITABLE_TEXT', 'Chooses a text far too hard or far too easy.', '{"question":"Which text is right for a learner in Grade 6?","wrong_answer":"a text with many unknown words on every line","correct_answer":"a text with a few new words"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a text with many unknown words on every line" next to the right answer in a new sentence and ask again.', 'A good book has a few new words, not every line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.SUITABLE_TEXT.M_TXT_OFF_TOPIC', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.SUITABLE_TEXT', 'Chooses a text on a different topic.', '{"question":"Which text is relevant for a project on Lake Victoria?","wrong_answer":"a text about the desert","correct_answer":"a text about Lake Victoria"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a text about the desert" next to the right answer in a new sentence and ask again.', 'Check the topic first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.INDEPENDENT_READING.M6_IR_ONE_GENRE', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.INDEPENDENT_READING', 'Reads only one kind of text.', '{"question":"Your log has only comics. What should you add?","wrong_answer":"more comics","correct_answer":"a novel, a poem and an information text"}'::jsonb, 'Comfort reading.', 'Offer "more comics" beside "a novel, a poem and an information text" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose a new kind of text each week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.INDEPENDENT_READING.M6_IR_NO_RECORD', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.INDEPENDENT_READING', 'Does not keep any record of reading.', '{"question":"How will you remember what you read this term?","wrong_answer":"I will remember","correct_answer":"write a line in my reading log"}'::jsonb, 'Records feel like extra work.', 'Offer "I will remember" beside "write a line in my reading log" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One line after each book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.INDEPENDENT_READING.M6_IR_ABANDONS', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.INDEPENDENT_READING', 'Abandons every book after a few pages.', '{"question":"The first chapter is slow. What do you do?","wrong_answer":"drop it","correct_answer":"read one more chapter before deciding"}'::jsonb, 'Instant interest is expected.', 'Offer "drop it" beside "read one more chapter before deciding" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give a book a chapter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T1_EXTENSIVE_READING.INDEPENDENT_READING.M6_IR_CANNOT_RECOMMEND', 'ENGL.G6.READIN.T1_EXTENSIVE_READING.INDEPENDENT_READING', 'Cannot say why a book is worth reading.', '{"question":"Tell a friend why to read your book.","wrong_answer":"It is nice.","correct_answer":"It has an exciting rescue in a flood."}'::jsonb, 'Opinion without reason.', 'Offer "It is nice." beside "It has an exciting rescue in a flood." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give one reason from the book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T1_WORD_CLASSES.DETERMINERS.M_DET_EACH_PLURAL', 'ENGL.G6.LANGUA.T1_WORD_CLASSES.DETERMINERS', 'Uses each with a plural noun or a plural verb.', '{"question":"Each of the girls ___ a bottle.","wrong_answer":"have","correct_answer":"has"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "have" next to the right answer in a new sentence and ask again.', 'Each means one at a time: one girl, one bottle, so the verb is singular.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T1_WORD_CLASSES.DETERMINERS.M_DET_LOTS_FORM', 'ENGL.G6.LANGUA.T1_WORD_CLASSES.DETERMINERS', 'Writes a lots of or a lot off.', '{"question":"We saw ___ goats at the market.","wrong_answer":"a lots of","correct_answer":"a lot of"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a lots of" next to the right answer in a new sentence and ask again.', 'Say the whole phrase: a lot of. Lots of has no a in front.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T1_WORD_CLASSES.DETERMINERS.M_DET_ENOUGH_AFTER', 'ENGL.G6.LANGUA.T1_WORD_CLASSES.DETERMINERS', 'Puts enough in the wrong place (enough big, instead of big enough).', '{"question":"The room is ___ for all of us.","wrong_answer":"enough big","correct_answer":"big enough"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "enough big" next to the right answer in a new sentence and ask again.', 'After an adjective, enough comes last: big enough. Before a noun it comes first: enough chairs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T1_WORD_CLASSES.DETERMINERS.M_DET_SOME_ANY', 'ENGL.G6.LANGUA.T1_WORD_CLASSES.DETERMINERS', 'Uses some where a question or a refusal needs any, or any in a plain statement.', '{"question":"There is not ___ milk left.","wrong_answer":"some","correct_answer":"any"}'::jsonb, 'Learns that some means a few and uses it in every sentence.', 'Offer "some" next to the right answer in a new sentence and ask again.', 'Some is for plain statements and offers. In a negative sentence use any.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS.M_FORM_SURNAME', 'ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS', 'Puts the first name in the surname space or the other way round.', '{"question":"Wanjiru Kamau Mwangi is filling in a form. Her surname is Mwangi. What goes in the box \"Surname\"?","wrong_answer":"Wanjiru","correct_answer":"Mwangi"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Wanjiru" next to the right answer in a new sentence and ask again.', 'The surname is the family name, the name shared with the family.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS.M_FORM_DATE_TODAY', 'ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS', 'Writes today''s date in the date of birth box.', '{"question":"Which goes in the box \"Date of birth\"?","wrong_answer":"the date today","correct_answer":"the day you were born"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the date today" next to the right answer in a new sentence and ask again.', 'Date of birth is the day you were born.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS.M_FORM_SKIP', 'ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS', 'Leaves a box empty instead of writing N/A or none.', '{"question":"The box \"Allergies\" does not apply to Peter. What should he write?","wrong_answer":"leave it empty","correct_answer":"N/A or none"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "leave it empty" next to the right answer in a new sentence and ask again.', 'An empty box looks as if you forgot. Write none or N/A.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS.M_FORM_BLOCK', 'ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS', 'Writes in small letters when the form asks for block letters.', '{"question":"The form says \"Write in BLOCK LETTERS\". Which way is right?","wrong_answer":"amina odhiambo","correct_answer":"AMINA ODHIAMBO"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "amina odhiambo" next to the right answer in a new sentence and ask again.', 'Block letters are all capital letters.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS.M_FORM_WRONG_FIELD', 'ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS', 'Plans a form with a field that has nothing to do with its purpose, or leaves out the one it needs.', '{"question":"A school wants someone to call in an emergency. Which field must the form have?","wrong_answer":"Favourite colour","correct_answer":"Parent or guardian phone number"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Favourite colour" next to the right answer in a new sentence and ask again.', 'Ask: what will the reader do with this information? Keep only what the purpose needs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS.M_FORM_SIGN_PRINT', 'ENGL.G6.WRITIN.T1_GUIDED_WRITING.FORM_FIELDS', 'Prints the name in the signature space.', '{"question":"What do you put in the box \"Signature\"?","wrong_answer":"your name in print","correct_answer":"your own handwritten signature"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "your name in print" next to the right answer in a new sentence and ask again.', 'A signature is your own handwriting of your name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.PROVERBS_USE.M6_PRV_LITERAL', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.PROVERBS_USE', 'Reads a proverb word for word.', '{"question":"What does \"A stitch in time saves nine\" mean?","wrong_answer":"Sewing is useful.","correct_answer":"Fix a small problem early so it does not grow."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Sewing is useful." next to the right answer in a new sentence and ask again.', 'A proverb gives advice by a picture. Ask: what is the lesson?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.PROVERBS_USE.M6_PRV_OPPOSITE', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.PROVERBS_USE', 'Takes the opposite lesson from a proverb.', '{"question":"What does \"Haste makes waste\" mean?","wrong_answer":"Hurry and you will get more done.","correct_answer":"Hurrying leads to mistakes and loss."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Hurry and you will get more done." next to the right answer in a new sentence and ask again.', 'Waste is a bad result: the proverb warns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.PROVERBS_USE.M_PRV_MIXED', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.PROVERBS_USE', 'Mixes two proverbs of a similar kind.', '{"question":"Which proverb tells us to keep what we already have?","wrong_answer":"Too many cooks spoil the broth.","correct_answer":"A bird in the hand is worth two in the bush."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Too many cooks spoil the broth." next to the right answer in a new sentence and ask again.', 'Match the lesson of each proverb, not only one word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.PROVERBS_USE.M_PRV_WORD', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.PROVERBS_USE', 'Finishes a proverb with the wrong word.', '{"question":"Where there is a will, there is a ___.","wrong_answer":"door","correct_answer":"way"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "door" next to the right answer in a new sentence and ask again.', 'Proverbs are fixed. Say it in full to remember it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.SIMILE_METAPHOR.M_SIM_METAPHOR_AS_SIMILE', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.SIMILE_METAPHOR', 'Calls a metaphor a simile.', '{"question":"Which sentence has a metaphor?","wrong_answer":"He ran like the wind.","correct_answer":"The thief was a hyena."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "He ran like the wind." next to the right answer in a new sentence and ask again.', 'A simile uses like or as. A metaphor says one thing IS another.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.SIMILE_METAPHOR.M_SIM_AS_LIKE', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.SIMILE_METAPHOR', 'Writes as ... like instead of as ... as.', '{"question":"He was as hungry ___ a wolf.","wrong_answer":"like","correct_answer":"as"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "like" next to the right answer in a new sentence and ask again.', 'The pattern is as ... as, or just like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.SIMILE_METAPHOR.M_SIM_WRONG_ANIMAL', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.SIMILE_METAPHOR', 'Uses the wrong animal or thing in a familiar simile.', '{"question":"As greedy as a ___.","wrong_answer":"giraffe","correct_answer":"hyena"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "giraffe" next to the right answer in a new sentence and ask again.', 'Similes are fixed: greedy as a hyena, brave as a lion.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.SIMILE_METAPHOR.M_SIM_PLAIN', 'ENGL.G6.LISTEN.T2_PRONUNCIATION_AND_LI.SIMILE_METAPHOR', 'Calls a plain statement a simile.', '{"question":"Which sentence has a simile?","wrong_answer":"My dog is big.","correct_answer":"My dog is as big as a calf."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "My dog is big." next to the right answer in a new sentence and ask again.', 'A simile compares two different things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS.M6_ELEM_MINOR_FOR_MAIN', 'ENGL.G6.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'Names a minor character for the main one.', '{"question":"Who is the story mostly about?","wrong_answer":"the shopkeeper","correct_answer":"Wanjiru"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the shopkeeper" next to the right answer in a new sentence and ask again.', 'The main character is in most of the events.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS.M6_ELEM_WRONG_PLACE', 'ENGL.G6.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'Names the wrong place.', '{"question":"Where did the story happen?","wrong_answer":"at the bus stop","correct_answer":"at the market"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "at the bus stop" next to the right answer in a new sentence and ask again.', 'Find the sentence that tells where.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS.M6_ELEM_ORDER_REVERSED', 'ENGL.G6.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'Reverses the order of events.', '{"question":"Put the events in order.","wrong_answer":"D, C, B, A","correct_answer":"A, B, C, D"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "D, C, B, A" next to the right answer in a new sentence and ask again.', 'Find the event that happens first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS.M6_ELEM_ORDER_SWAPPED', 'ENGL.G6.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'Swaps two events that are next to each other.', '{"question":"Put the events in order.","wrong_answer":"A, C, B, D","correct_answer":"A, B, C, D"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "A, C, B, D" next to the right answer in a new sentence and ask again.', 'Check each pair: which happened first?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS.M6_ELEM_MIXES_CHARACTER_PLACE', 'ENGL.G6.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'Gives a place when a character is asked, or the other way round.', '{"question":"Who helped the boy?","wrong_answer":"the village","correct_answer":"his aunt"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the village" next to the right answer in a new sentence and ask again.', 'A character is a person or animal; a place is where.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.PREDICT.M6_PRED_NO_CLUE', 'ENGL.G6.READIN.T2_INTENSIVE_READING.PREDICT', 'Predicts something with no clue in the passage.', '{"question":"What will probably happen next?","wrong_answer":"a lion will arrive","correct_answer":"the children will keep working"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a lion will arrive" next to the right answer in a new sentence and ask again.', 'A prediction needs a clue from the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.PREDICT.M6_PRED_CONTRADICTS', 'ENGL.G6.READIN.T2_INTENSIVE_READING.PREDICT', 'Predicts something that goes against the passage.', '{"question":"What will probably happen next?","wrong_answer":"she will give up","correct_answer":"she will try again"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "she will give up" next to the right answer in a new sentence and ask again.', 'The prediction must agree with what the passage shows about the character.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.PREDICT.M6_PRED_ALREADY_HAPPENED', 'ENGL.G6.READIN.T2_INTENSIVE_READING.PREDICT', 'Gives something that has already happened as a prediction.', '{"question":"What will probably happen next?","wrong_answer":"she carried the bag","correct_answer":"she will set off"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "she carried the bag" next to the right answer in a new sentence and ask again.', 'A prediction is about what comes after the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M6_FACT_NEARBY_DETAIL', 'ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Picks a detail that is close to the answer but is not the answer.', '{"question":"What did she carry?","wrong_answer":"a basket","correct_answer":"a bucket"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a basket" next to the right answer in a new sentence and ask again.', 'Read the exact sentence the question points to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M6_FACT_OUTSIDE_KNOWLEDGE', 'ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Answers from what he or she knows, not from the passage.', '{"question":"What did they use to make it?","wrong_answer":"grass","correct_answer":"old rags"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "grass" next to the right answer in a new sentence and ask again.', 'The answer is in the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M6_FACT_MISSES_STATED', 'ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says the passage does not say something that it does say.', '{"question":"Is it true, false or not stated?","wrong_answer":"Not stated","correct_answer":"True"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Not stated" next to the right answer in a new sentence and ask again.', 'Search the passage again for the sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M6_FACT_FALSE_AS_TRUE', 'ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says true when the passage says something different.', '{"question":"Is it true, false or not stated?","wrong_answer":"True","correct_answer":"False"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "True" next to the right answer in a new sentence and ask again.', 'Compare your statement with the sentence in the passage word by word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M6_FACT_FALSE_AS_NOT_STATED', 'ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says not stated when the passage says the opposite.', '{"question":"Is it true, false or not stated?","wrong_answer":"Not stated","correct_answer":"False"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Not stated" next to the right answer in a new sentence and ask again.', 'If the passage says the opposite, the statement is false.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M6_FACT_NOT_STATED_AS_TRUE', 'ENGL.G6.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says true for something that sounds likely but is not written.', '{"question":"Is it true, false or not stated?","wrong_answer":"True","correct_answer":"Not stated"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "True" next to the right answer in a new sentence and ask again.', 'Find the line. If you cannot, it is not stated.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M6_INFER_CONTRADICTS', 'ENGL.G6.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Gives an answer that the passage goes against.', '{"question":"Why did she smile?","wrong_answer":"She was angry.","correct_answer":"She was pleased."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "She was angry." next to the right answer in a new sentence and ask again.', 'Check each answer against the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M6_INFER_OVERREACH', 'ENGL.G6.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Gives an answer that goes too far beyond the clues.', '{"question":"What can you tell about her?","wrong_answer":"She is the richest woman in town.","correct_answer":"She is kind."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "She is the richest woman in town." next to the right answer in a new sentence and ask again.', 'Stay with what the clues show.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M6_INFER_REPEATS_TEXT', 'ENGL.G6.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Copies a sentence from the passage as the inference.', '{"question":"Why did he feel sad?","wrong_answer":"The ball burst.","correct_answer":"He loved the game and could not play."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The ball burst." next to the right answer in a new sentence and ask again.', 'An inference explains; it does not repeat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.IMAGERY.M_IMG_FACT_LINE', 'ENGL.G6.READIN.T2_INTENSIVE_READING.IMAGERY', 'Chooses the line that only gives a fact, not the one that paints a picture.', '{"question":"Which line paints the clearest picture?","wrong_answer":"The market opens at six.","correct_answer":"Heaps of red tomatoes glowed in the early sun."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The market opens at six." next to the right answer in a new sentence and ask again.', 'Look for colours, sounds and movement.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.IMAGERY.M_IMG_WRONG_PICTURE', 'ENGL.G6.READIN.T2_INTENSIVE_READING.IMAGERY', 'Picks a picture the words do not show.', '{"question":"What picture does the poet want you to see?","wrong_answer":"a quiet night","correct_answer":"a busy market"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a quiet night" next to the right answer in a new sentence and ask again.', 'Read the key words again: what do they show?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.IMAGERY.M_IMG_ONE_WORD', 'ENGL.G6.READIN.T2_INTENSIVE_READING.IMAGERY', 'Chooses a picture from one word, ignoring the rest.', '{"question":"What picture does the poet want you to see?","wrong_answer":"a river","correct_answer":"rain on a roof"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a river" next to the right answer in a new sentence and ask again.', 'Use all the words, not one word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.CHARACTER_JUDGE.M_CHAR_NAME_ONLY', 'ENGL.G6.READIN.T2_INTENSIVE_READING.CHARACTER_JUDGE', 'Judges a character from one word or the name.', '{"question":"Which word best describes her?","wrong_answer":"selfish","correct_answer":"generous"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "selfish" next to the right answer in a new sentence and ask again.', 'Look at what she does and says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.CHARACTER_JUDGE.M_CHAR_OPPOSITE', 'ENGL.G6.READIN.T2_INTENSIVE_READING.CHARACTER_JUDGE', 'Chooses the opposite trait.', '{"question":"Which word best describes him?","wrong_answer":"lazy","correct_answer":"hardworking"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "lazy" next to the right answer in a new sentence and ask again.', 'Check the actions: do they show effort or none?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.CHARACTER_JUDGE.M_CHAR_WRONG_EVIDENCE', 'ENGL.G6.READIN.T2_INTENSIVE_READING.CHARACTER_JUDGE', 'Picks a line that does not show the trait as evidence.', '{"question":"Which line shows that she is kind?","wrong_answer":"She lived in a village.","correct_answer":"She gave her lunch to a hungry boy."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "She lived in a village." next to the right answer in a new sentence and ask again.', 'Evidence is what the character does or says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.PREDICT.M6_PRED_TITLE_IGNORED', 'ENGL.G6.READIN.T2_INTENSIVE_READING.PREDICT', 'Predicts without using the title.', '{"question":"Title: \"The Flood that Saved Us\". What will the story be about?","wrong_answer":"a football match","correct_answer":"a flood that ends well"}'::jsonb, 'Titles are skipped.', 'Offer "a football match" beside "a flood that ends well" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The title is the first clue.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M6_INFER_OWN_FEELING', 'ENGL.G6.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Gives the reader''s feeling instead of the character''s.', '{"question":"\"Kamau clenched his fists.\" How did Kamau feel?","wrong_answer":"I would be scared","correct_answer":"angry"}'::jsonb, 'The question is read as about the reader.', 'Offer "I would be scared" beside "angry" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: what does the clue show about the character?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.IMAGERY.M6_IMG_ADDS', 'ENGL.G6.READIN.T2_INTENSIVE_READING.IMAGERY', 'Adds details to the picture that the text does not give.', '{"question":"\"Smoke curled from the hut.\" Which detail is in the text?","wrong_answer":"children played outside","correct_answer":"smoke rising from the hut"}'::jsonb, 'Imagination goes beyond the words.', 'Offer "children played outside" beside "smoke rising from the hut" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Picture only what the words say.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T2_INTENSIVE_READING.CHARACTER_JUDGE.M6_CHAR_ONE_ACT', 'ENGL.G6.READIN.T2_INTENSIVE_READING.CHARACTER_JUDGE', 'Judges a character from one action and ignores the rest.', '{"question":"Otieno shouted once but helped everyone all day. Otieno is ...","wrong_answer":"rude","correct_answer":"helpful"}'::jsonb, 'One striking action outweighs the pattern.', 'Offer "rude" beside "helpful" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at all the character does and says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T2_WORD_CLASSES.CONCRETE_ABSTRACT.M_NOUN_FEELING_CONCRETE', 'ENGL.G6.LANGUA.T2_WORD_CLASSES.CONCRETE_ABSTRACT', 'Thinks a feeling or an idea is concrete because it is real.', '{"question":"Which noun is abstract: river, kindness, table, dog.","wrong_answer":"river","correct_answer":"kindness"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "river" next to the right answer in a new sentence and ask again.', 'Ask: can I touch it, see it or hear it? Kindness is only in our minds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T2_WORD_CLASSES.CONCRETE_ABSTRACT.M_NOUN_PLACE_ABSTRACT', 'ENGL.G6.LANGUA.T2_WORD_CLASSES.CONCRETE_ABSTRACT', 'Thinks a place or a group is abstract.', '{"question":"Which noun is concrete: freedom, market, honesty, courage.","wrong_answer":"freedom","correct_answer":"market"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "freedom" next to the right answer in a new sentence and ask again.', 'A market is a place you can walk to, so it is concrete.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T2_WORD_CLASSES.CONCRETE_ABSTRACT.M_NOUN_ADJECTIVE_FORM', 'ENGL.G6.LANGUA.T2_WORD_CLASSES.CONCRETE_ABSTRACT', 'Uses the adjective where the abstract noun is needed (honest for honesty).', '{"question":"The headteacher praised her ___.","wrong_answer":"honest","correct_answer":"honesty"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "honest" next to the right answer in a new sentence and ask again.', 'After her, a noun is needed. The noun for honest is honesty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T2_WORD_CLASSES.CONCRETE_ABSTRACT.M_NOUN_SENSE_ABSTRACT', 'ENGL.G6.LANGUA.T2_WORD_CLASSES.CONCRETE_ABSTRACT', 'Thinks a sound, a smell or a time word is concrete.', '{"question":"Which noun is abstract: bell, music, drum, radio.","wrong_answer":"bell","correct_answer":"music"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "bell" next to the right answer in a new sentence and ask again.', 'You can hear music but you cannot hold it; the bell and radio are things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PARAGRAPH_ORDER.M_PARA_DETAIL_OPENS', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PARAGRAPH_ORDER', 'Opens a paragraph with a small detail instead of the main idea.', '{"question":"Which sentence is the best topic sentence?","wrong_answer":"The bus was blue.","correct_answer":"Our school trip to Nakuru taught us many things."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The bus was blue." next to the right answer in a new sentence and ask again.', 'The topic sentence tells what the whole paragraph is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PARAGRAPH_ORDER.M_PARA_OFF_TOPIC', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PARAGRAPH_ORDER', 'Keeps a sentence that does not belong to the paragraph''s idea.', '{"question":"A paragraph about our school garden ends: \"We also won a football match.\" Keep it?","wrong_answer":"Yes, keep it","correct_answer":"No, it does not belong"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Yes, keep it" next to the right answer in a new sentence and ask again.', 'Check each sentence: does it help the main idea?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PARAGRAPH_ORDER.M_PARA_ORDER', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PARAGRAPH_ORDER', 'Puts the sentences in the order they come to mind, not the logical order.', '{"question":"Put these sentences in order.","wrong_answer":"C, A, B, D","correct_answer":"A, B, C, D"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "C, A, B, D" next to the right answer in a new sentence and ask again.', 'Look for first, next, then, finally and for the sentence that sums up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PARAGRAPH_ORDER.M_PARA_CONCLUSION', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PARAGRAPH_ORDER', 'Ends with a new idea instead of a closing sentence.', '{"question":"Which sentence best ends the paragraph?","wrong_answer":"Next week we start a new project.","correct_answer":"So the trip was a day we will remember."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Next week we start a new project." next to the right answer in a new sentence and ask again.', 'The last sentence sums up the paragraph; it does not open a new topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PLAN_COMPOSITION.M6_PC_OFF_TOPIC', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PLAN_COMPOSITION', 'Keeps ideas that leave the topic.', '{"question":"Topic: A religious celebration. Which idea does not belong?","wrong_answer":"We sang in church.","correct_answer":"My father bought a new car last year."}'::jsonb, 'All ideas are kept.', 'Offer "We sang in church." beside "My father bought a new car last year." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Cross out ideas that leave the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PLAN_COMPOSITION.M6_PC_NO_ORDER', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PLAN_COMPOSITION', 'Lists ideas with no order.', '{"question":"Order: prayers, went home, arrived at the mosque","wrong_answer":"went home, prayers, arrived","correct_answer":"arrived, prayers, went home"}'::jsonb, 'Ideas are written as they come.', 'Offer "went home, prayers, arrived" beside "arrived, prayers, went home" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Number them in the order they happen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PLAN_COMPOSITION.M6_PC_TOPIC_TOO_WIDE', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PLAN_COMPOSITION', 'Chooses a topic too wide to write about well.', '{"question":"Better topic for a short composition?","wrong_answer":"Everything about Kenya","correct_answer":"Our Eid celebration last year"}'::jsonb, 'Wide topics seem to offer more to say.', 'Offer "Everything about Kenya" beside "Our Eid celebration last year" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose a topic you can cover in a page.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PLAN_COMPOSITION.M6_PC_PLAN_TOO_LONG', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.PLAN_COMPOSITION', 'Writes the full composition as the plan.', '{"question":"What does a plan look like?","wrong_answer":"full paragraphs","correct_answer":"short notes under headings"}'::jsonb, 'Planning and writing are not told apart.', 'Offer "full paragraphs" beside "short notes under headings" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A plan is short notes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION.M6_OC_DRIFT', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION', 'Drifts from the topic in the middle.', '{"question":"Topic: Diwali in our town. A paragraph is about school exams. Fit?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'One idea leads to another.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check each paragraph against the title.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION.M6_OC_ONE_BLOCK', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION', 'Writes one long block.', '{"question":"Where does a new paragraph start?","wrong_answer":"nowhere","correct_answer":"at each new idea"}'::jsonb, 'Paragraphing is skipped under time pressure.', 'Offer "nowhere" beside "at each new idea" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'New idea, new paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION.M6_OC_REPEATED_LINKS', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION', 'Uses the same linking word again and again.', '{"question":"Improve: Then ... Then ... Then ...","wrong_answer":"Then ... Then ... Then","correct_answer":"After that ... Later ... Finally"}'::jsonb, 'A small set of linking words.', 'Offer "Then ... Then ... Then" beside "After that ... Later ... Finally" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Vary linking words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION.M6_OC_FORCED_IDIOMS', 'ENGL.G6.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION', 'Packs idioms and proverbs in where they do not fit.', '{"question":"Is \"Every cloud has a silver lining\" right in a sentence about buying bread?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Idioms are added for marks.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use an idiom only where its meaning fits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_TALK.M_POL_BLUNT', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_TALK', 'Interrupts or asks in a blunt way (What? Shut up!).', '{"question":"Your friend is speaking and you want to add something. What do you say?","wrong_answer":"Stop! Now it is my turn.","correct_answer":"Excuse me, may I add something?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Stop! Now it is my turn." next to the right answer in a new sentence and ask again.', 'Say excuse me, wait for a pause, and ask.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_TALK.M_POL_PHONE_START', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_TALK', 'Answers the telephone without a greeting or a name.', '{"question":"You answer your home telephone. What is the best way to begin?","wrong_answer":"Who is this?","correct_answer":"Hello, this is Amina speaking. How may I help you?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Who is this?" next to the right answer in a new sentence and ask again.', 'Greet, say who you are and offer help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_TALK.M_POL_CLARIFY', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_TALK', 'Asks for clarification in a rude way (What?).', '{"question":"You did not hear what the teacher said. What do you say?","wrong_answer":"What? Say it again.","correct_answer":"I beg your pardon. Could you say that again, please?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "What? Say it again." next to the right answer in a new sentence and ask again.', 'Ask politely: pardon, could you repeat that, please.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_TALK.M_POL_MESSAGE', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_TALK', 'Does not offer to take a message when the person is not in.', '{"question":"The caller asks for your mother, who is out. What is the polite reply?","wrong_answer":"She is not here. Bye.","correct_answer":"She is out at the moment. May I take a message?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "She is not here. Bye." next to the right answer in a new sentence and ask again.', 'Say where the person is and offer to take a message.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M6_PS_TOUR_TORE', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Says /ʊə/ (tour) as /ɔː/ (tore).', '{"question":"Say: tour","wrong_answer":"tore","correct_answer":"tour (too-uh)"}'::jsonb, 'The diphthong is new and is replaced by the nearest pure vowel.', 'Offer "tore" beside "tour (too-uh)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with oo and slide to uh: too-uh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M6_PS_PHONE_FON', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Says /əʊ/ (phone) as a short pure o.', '{"question":"Say: phone","wrong_answer":"fon","correct_answer":"phone (foh-oon)"}'::jsonb, 'Home languages have a pure o; the glide is dropped.', 'Offer "fon" beside "phone (foh-oon)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Glide from uh to oo: phone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M6_PS_H_DROP_ADD', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Drops /h/ where it is said, or adds it where it is not.', '{"question":"Say: The hen is in the house.","wrong_answer":"The en is in the ouse.","correct_answer":"The hen is in the house."}'::jsonb, 'Some speakers drop h; others add it to vowel words by overcorrecting.', 'Offer "The en is in the ouse." beside "The hen is in the house." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Breathe out a small h at the start of hen and house; none in hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M6_PS_V_F', 'ENGL.G6.LISTEN.T3_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Says /f/ for /v/.', '{"question":"Say: vaccine","wrong_answer":"faccine","correct_answer":"vaccine"}'::jsonb, 'No /v/ in the home language.', 'Offer "faccine" beside "vaccine" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Teeth on lip and voice on: v.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T3_INTENSIVE_READING.CONTEXT_CLUES.M6_CTX_COMMON_MEANING', 'ENGL.G6.READIN.T3_INTENSIVE_READING.CONTEXT_CLUES', 'Picks the usual meaning of a word instead of the one that fits.', '{"question":"In the passage, what does \"ran\" mean?","wrong_answer":"moved fast on foot","correct_answer":"worked or managed"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "moved fast on foot" next to the right answer in a new sentence and ask again.', 'Try each meaning in the sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T3_INTENSIVE_READING.CONTEXT_CLUES.M6_CTX_LOOKS_LIKE', 'ENGL.G6.READIN.T3_INTENSIVE_READING.CONTEXT_CLUES', 'Chooses a meaning because the word looks like another word.', '{"question":"In the passage, what does the word mean?","wrong_answer":"a word it looks like","correct_answer":"the meaning from the clues"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a word it looks like" next to the right answer in a new sentence and ask again.', 'Use the clues, not how the word looks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T3_INTENSIVE_READING.CONTEXT_CLUES.M6_CTX_OPPOSITE', 'ENGL.G6.READIN.T3_INTENSIVE_READING.CONTEXT_CLUES', 'Picks the opposite meaning.', '{"question":"In the passage, what does the word mean?","wrong_answer":"the opposite","correct_answer":"the right meaning"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the opposite" next to the right answer in a new sentence and ask again.', 'See if the sentence says but or because.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T3_INTENSIVE_READING.CONTEXT_CLUES.M6_CTX_WRONG_CLUE', 'ENGL.G6.READIN.T3_INTENSIVE_READING.CONTEXT_CLUES', 'Picks words that do not explain the word as the clue.', '{"question":"Which words in the passage help you with the word?","wrong_answer":"the title","correct_answer":"the sentence that explains it"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the title" next to the right answer in a new sentence and ask again.', 'A clue is close to the word and explains it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.CORRELATIVE.M_CORR_NEITHER_OR', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.CORRELATIVE', 'Writes neither ... or instead of neither ... nor.', '{"question":"Neither Atieno ___ Juma knew the answer.","wrong_answer":"or","correct_answer":"nor"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "or" next to the right answer in a new sentence and ask again.', 'Neither always goes with nor, either with or.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.CORRELATIVE.M_CORR_BOTH_OR', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.CORRELATIVE', 'Writes both ... or, or both ... nor.', '{"question":"Both Mary ___ Peter passed the test.","wrong_answer":"or","correct_answer":"and"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "or" next to the right answer in a new sentence and ask again.', 'Both means the two together, so and joins them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.CORRELATIVE.M_CORR_EITHER_NOR', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.CORRELATIVE', 'Writes either ... nor, or either ... and.', '{"question":"You may either walk ___ take a matatu.","wrong_answer":"nor","correct_answer":"or"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "nor" next to the right answer in a new sentence and ask again.', 'Either is a choice, so it goes with or.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.CORRELATIVE.M_CORR_NOT_ONLY_AND', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.CORRELATIVE', 'Writes not only ... and, not only ... also, leaving out but.', '{"question":"He is not only clever ___ also hardworking.","wrong_answer":"and","correct_answer":"but"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "and" next to the right answer in a new sentence and ask again.', 'The pair is not only ... but also.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.CORRELATIVE.M_CORR_NEITHER_NOT', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.CORRELATIVE', 'Adds not to a neither ... nor sentence (a double negative).', '{"question":"Neither Ouma nor Wanjiru ___ late.","wrong_answer":"was not","correct_answer":"was"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "was not" next to the right answer in a new sentence and ask again.', 'Neither and nor already say no. Do not add not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.SHOW_PATTERN.M_SHOW_INVERSION', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.SHOW_PATTERN', 'Turns the verb round after the question word (Show me where is the library).', '{"question":"Show me where ___.","wrong_answer":"is the library","correct_answer":"the library is"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "is the library" next to the right answer in a new sentence and ask again.', 'It is not a question, so the order stays: subject, then verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.SHOW_PATTERN.M_SHOW_DO_SUPPORT', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.SHOW_PATTERN', 'Adds do or does after the question word (Tell me how does it work).', '{"question":"Tell me how ___.","wrong_answer":"does it work","correct_answer":"it works"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "does it work" next to the right answer in a new sentence and ask again.', 'Leave out do and does here; the verb takes its normal ending.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.SHOW_PATTERN.M_SHOW_WORD_MISSING', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.SHOW_PATTERN', 'Leaves out the question word (Show me the shop is).', '{"question":"Please show me ___ the shop is.","wrong_answer":"that","correct_answer":"where"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "that" next to the right answer in a new sentence and ask again.', 'The question word tells what you want to know: where, how or who.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.SHOW_PATTERN.M_SHOW_QMARK', 'ENGL.G6.LANGUA.T3_CORRELATIVE_CONJUNCT.SHOW_PATTERN', 'Ends the sentence with a question mark although it is a request or a statement.', '{"question":"Tell me who won the race.","wrong_answer":"Tell me who won the race?","correct_answer":"Tell me who won the race."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Tell me who won the race?" next to the right answer in a new sentence and ask again.', 'A question mark is only for a real question. This sentence tells.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.ABBREVIATIONS.M_ABBR_ACRONYM_ANY', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.ABBREVIATIONS', 'Calls every short form an acronym.', '{"question":"Which of these is an acronym: Mr, Dr, UNICEF, etc.","wrong_answer":"Mr","correct_answer":"UNICEF"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Mr" next to the right answer in a new sentence and ask again.', 'An acronym is said as a word. An abbreviation is a short form said letter by letter or in full.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.ABBREVIATIONS.M_ABBR_WRONG_EXPAND', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.ABBREVIATIONS', 'Expands an acronym with the wrong words.', '{"question":"What does KNEC stand for?","wrong_answer":"Kenya National Education Centre","correct_answer":"Kenya National Examinations Council"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Kenya National Education Centre" next to the right answer in a new sentence and ask again.', 'Each letter is the first letter of a word in the name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.ABBREVIATIONS.M_ABBR_ETC_EG', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.ABBREVIATIONS', 'Mixes etc., e.g. and i.e.', '{"question":"Which short form means \"for example\"?","wrong_answer":"etc.","correct_answer":"e.g."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "etc." next to the right answer in a new sentence and ask again.', 'Etc. means and so on; e.g. means for example; i.e. means that is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.ABBREVIATIONS.M_ABBR_SHORT_FORM', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.ABBREVIATIONS', 'Writes the wrong short form of a title or word.', '{"question":"The short form of Doctor is ___.","wrong_answer":"Dc.","correct_answer":"Dr"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Dc." next to the right answer in a new sentence and ask again.', 'Keep the first and last letters or the first letters of the word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.NUMERALS.M_NUM_FOURTY', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.NUMERALS', 'Writes fourty for forty, or forteen and ninty.', '{"question":"Which is the correct spelling of 40?","wrong_answer":"fourty","correct_answer":"forty"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "fourty" next to the right answer in a new sentence and ask again.', 'Four loses its u in forty, but fourteen keeps it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.NUMERALS.M_NUM_START_FIGURE', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.NUMERALS', 'Begins a sentence with a figure.', '{"question":"Which sentence begins correctly?","wrong_answer":"25 learners were absent.","correct_answer":"Twenty-five learners were absent."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "25 learners were absent." next to the right answer in a new sentence and ask again.', 'A sentence should not begin with a figure. Spell the number out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.NUMERALS.M_NUM_ORDINAL_END', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.NUMERALS', 'Writes the wrong ending of an ordinal (2th, 3th, 1th).', '{"question":"The correct way to write second as a figure is ___.","wrong_answer":"2th","correct_answer":"2nd"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "2th" next to the right answer in a new sentence and ask again.', 'The endings are 1st, 2nd, 3rd, then th for 4th onward.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.NUMERALS.M_NUM_EIGHTH', 'ENGL.G6.WRITIN.T3_MECHANICS_OF_WRITING.NUMERALS', 'Spells eighth or ninth wrongly (eigth, nineth).', '{"question":"Which is the correct spelling of 8th in words?","wrong_answer":"eigth","correct_answer":"eighth"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "eigth" next to the right answer in a new sentence and ask again.', 'Eight keeps its t: eighth. Nine loses its e: ninth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.RESCUE_WORDS.M_RES_VEHICLE_PERSON', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.RESCUE_WORDS', 'Mixes the vehicle and the person (ambulance and paramedic).', '{"question":"The ___ gave first aid to the injured man.","wrong_answer":"ambulance","correct_answer":"paramedic"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "ambulance" next to the right answer in a new sentence and ask again.', 'The ambulance is the vehicle; the paramedic is the trained person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.RESCUE_WORDS.M_RES_EVACUATE', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.RESCUE_WORDS', 'Thinks evacuate means to rescue a person from fire, not to move people out of a place.', '{"question":"Everyone had to ___ the building when the alarm rang.","wrong_answer":"rescue","correct_answer":"evacuate"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "rescue" next to the right answer in a new sentence and ask again.', 'Evacuate: leave a dangerous place. Rescue: save someone in danger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.RESCUE_WORDS.M_RES_SIREN_ALARM', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.RESCUE_WORDS', 'Uses the wrong word for a warning sound or sign.', '{"question":"We heard the ___ of the fire engine from far away.","wrong_answer":"alarm","correct_answer":"siren"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "alarm" next to the right answer in a new sentence and ask again.', 'A siren is the loud warning sound of a vehicle. An alarm warns in a building.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M6_WS_NOUN_VERB_SAME', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Uses the same stress for the noun and the verb.', '{"question":"They will ___ (permit) us to enter.","wrong_answer":"PERmit","correct_answer":"perMIT"}'::jsonb, 'The stress-meaning rule is not known.', 'Offer "PERmit" beside "perMIT" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Noun: strong first part. Verb: strong second part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M6_WS_SMALL_WORDS', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Stresses helping words and articles in a sentence.', '{"question":"Say: The AMbulance CAME QUICKly.","wrong_answer":"THE ambulance CAME quickly with every word strong","correct_answer":"The AMbulance came QUICKly"}'::jsonb, 'Every word is given equal weight.', 'Offer "THE ambulance CAME quickly with every word strong" beside "The AMbulance came QUICKly" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stress the words that carry meaning; keep the, a and is weak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M6_WS_PENULT', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Puts the stress on the next-to-last syllable of every word.', '{"question":"Say: emergency","wrong_answer":"emer-GEN-cy","correct_answer":"e-MER-gen-cy"}'::jsonb, 'Kiswahili places stress on the next-to-last syllable.', 'Offer "emer-GEN-cy" beside "e-MER-gen-cy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Clap it: e-MER-gen-cy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M6_WS_EQUAL', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Gives every syllable equal stress.', '{"question":"Say: helicopter","wrong_answer":"HE-LI-COP-TER","correct_answer":"HE-li-cop-ter"}'::jsonb, 'Syllable-timed home languages.', 'Offer "HE-LI-COP-TER" beside "HE-li-cop-ter" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One strong beat; the others short.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.RESCUE_WORDS.M6_RES_FIRST_AID_CPR', 'ENGL.G6.LISTEN.T4_PRONUNCIATION_AND_VO.RESCUE_WORDS', 'Thinks first aid means only bandaging.', '{"question":"Giving a person breaths and chest pushes is part of ...","wrong_answer":"surgery","correct_answer":"first aid (CPR)"}'::jsonb, 'First aid is pictured as plasters only.', 'Offer "surgery" beside "first aid (CPR)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'First aid is any help given before the doctor comes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T4_INTENSIVE_READING.READ_VISUALS.M6_RV_PREDICT_ONE_DETAIL', 'ENGL.G6.READIN.T4_INTENSIVE_READING.READ_VISUALS', 'Predicts from one small detail and ignores the main picture.', '{"question":"A picture shows a flooded village with a helicopter. Predict.","wrong_answer":"There will be a football match.","correct_answer":"People will be rescued from the flood."}'::jsonb, 'A small corner of the picture is used.', 'Offer "There will be a football match." beside "People will be rescued from the flood." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at the whole picture and the caption.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T4_INTENSIVE_READING.READ_VISUALS.M6_RV_DECORATION', 'ENGL.G6.READIN.T4_INTENSIVE_READING.READ_VISUALS', 'Judges a visual as relevant because it is attractive.', '{"question":"A text on fire safety has a picture of flowers. Relevant?","wrong_answer":"Yes, it is beautiful","correct_answer":"No, it does not help the text"}'::jsonb, 'Beauty is taken as relevance.', 'Offer "Yes, it is beautiful" beside "No, it does not help the text" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: does it help me understand the text?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T4_INTENSIVE_READING.READ_VISUALS.M6_RV_CAPTION_IGNORED', 'ENGL.G6.READIN.T4_INTENSIVE_READING.READ_VISUALS', 'Ignores the caption.', '{"question":"What does the caption under the picture add?","wrong_answer":"nothing","correct_answer":"it says where and when the picture was taken"}'::jsonb, 'Captions are small and skipped.', 'Offer "nothing" beside "it says where and when the picture was taken" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the caption: it explains the picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T4_INTENSIVE_READING.READ_VISUALS.M6_RV_DIAGRAM_ORDER', 'ENGL.G6.READIN.T4_INTENSIVE_READING.READ_VISUALS', 'Reads a diagram in the wrong order.', '{"question":"Arrows show the steps of calling 999. Which first?","wrong_answer":"the last box","correct_answer":"the box the first arrow starts from"}'::jsonb, 'Arrows are not followed.', 'Offer "the last box" beside "the box the first arrow starts from" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Follow the arrows from the start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T4_WORD_CLASSES.RELATIVE_PRONOUNS.M_REL_WHICH_PERSON', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.RELATIVE_PRONOUNS', 'Uses which for a person (the girl which won).', '{"question":"The girl ___ won the race is my cousin.","wrong_answer":"which","correct_answer":"who"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "which" next to the right answer in a new sentence and ask again.', 'Who is for people, which is for things and animals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T4_WORD_CLASSES.RELATIVE_PRONOUNS.M_REL_WHO_THING', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.RELATIVE_PRONOUNS', 'Uses who for a thing (the book who).', '{"question":"This is the book ___ I bought yesterday.","wrong_answer":"who","correct_answer":"which"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "who" next to the right answer in a new sentence and ask again.', 'A book is a thing, so which.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T4_WORD_CLASSES.RELATIVE_PRONOUNS.M_REL_WHOSE_WHO', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.RELATIVE_PRONOUNS', 'Uses who where whose (belonging) is needed.', '{"question":"The boy ___ bag was stolen cried.","wrong_answer":"who","correct_answer":"whose"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "who" next to the right answer in a new sentence and ask again.', 'The bag belongs to the boy. Belonging is whose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T4_WORD_CLASSES.RELATIVE_PRONOUNS.M_REL_DOUBLE', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.RELATIVE_PRONOUNS', 'Adds a second pronoun (the boy who he won).', '{"question":"The teacher ___ taught us Maths is kind.","wrong_answer":"who she","correct_answer":"who"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "who she" next to the right answer in a new sentence and ask again.', 'The word who already does the work of he or she.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T4_WORD_CLASSES.RELATIVE_PRONOUNS.M_REL_WHOM_WHO', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.RELATIVE_PRONOUNS', 'Uses who for the object of a verb or after a preposition where whom is needed.', '{"question":"To ___ did you give the letter?","wrong_answer":"who","correct_answer":"whom"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "who" next to the right answer in a new sentence and ask again.', 'After to, with, for, use whom. Whom is for the one who receives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T4_WORD_CLASSES.INDEFINITE_PRONOUNS.M_IND_ANY_STATEMENT', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.INDEFINITE_PRONOUNS', 'Uses any- in a plain statement (I saw anybody).', '{"question":"I saw ___ at the gate.","wrong_answer":"anybody","correct_answer":"somebody"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "anybody" next to the right answer in a new sentence and ask again.', 'In a plain positive sentence use some-. Any- is for questions and negatives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T4_WORD_CLASSES.INDEFINITE_PRONOUNS.M_IND_DOUBLE_NEG', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.INDEFINITE_PRONOUNS', 'Writes a double negative (I did not see nobody).', '{"question":"I did not meet ___ on the road.","wrong_answer":"nobody","correct_answer":"anybody"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "nobody" next to the right answer in a new sentence and ask again.', 'One negative is enough. After not, use any-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T4_WORD_CLASSES.INDEFINITE_PRONOUNS.M_IND_PLURAL_VERB', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.INDEFINITE_PRONOUNS', 'Uses a plural verb after everyone or everybody.', '{"question":"Everyone ___ here.","wrong_answer":"are","correct_answer":"is"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "are" next to the right answer in a new sentence and ask again.', 'Everyone sounds like many, but the word is singular.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T4_WORD_CLASSES.INDEFINITE_PRONOUNS.M_IND_NOONE', 'ENGL.G6.LANGUA.T4_WORD_CLASSES.INDEFINITE_PRONOUNS', 'Writes noone or no-one as one word.', '{"question":"There was ___ in the hall.","wrong_answer":"noone","correct_answer":"no one"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "noone" next to the right answer in a new sentence and ask again.', 'No one is two words. Nobody is one word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_LETTER.M_LET_CLOSING', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_LETTER', 'Closes Dear Sir with Yours sincerely, or Dear Mr Otieno with Yours faithfully.', '{"question":"A letter begins \"Dear Sir\". How should it end?","wrong_answer":"Yours sincerely","correct_answer":"Yours faithfully"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Yours sincerely" next to the right answer in a new sentence and ask again.', 'Dear Sir or Madam goes with faithfully. A named person goes with sincerely.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_LETTER.M_LET_INFORMAL', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_LETTER', 'Uses friendly language in a formal letter.', '{"question":"Which line is right for a formal invitation?","wrong_answer":"Hi! Come to our party, it will be fun.","correct_answer":"You are kindly invited to our school open day."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Hi! Come to our party, it will be fun." next to the right answer in a new sentence and ask again.', 'A formal letter is polite and plain, with no slang or short forms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_LETTER.M_LET_ADDRESS', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_LETTER', 'Puts the writer''s address in the wrong place.', '{"question":"Where does the writer''s address go in a formal letter?","wrong_answer":"at the bottom","correct_answer":"at the top right"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "at the bottom" next to the right answer in a new sentence and ask again.', 'The sender''s address begins the letter, at the top right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_LETTER.M_LET_NO_SUBJECT', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_LETTER', 'Leaves out the subject line.', '{"question":"Which part tells the reader what the letter is about?","wrong_answer":"the closing","correct_answer":"the subject line"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the closing" next to the right answer in a new sentence and ask again.', 'The subject heading comes under the greeting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_LETTER.M_LET_SIGNATURE', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_LETTER', 'Writes the name but no signature or forgets the position.', '{"question":"Where does the signature go?","wrong_answer":"above the greeting","correct_answer":"under the closing"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "above the greeting" next to the right answer in a new sentence and ask again.', 'Greeting, body, closing, then signature and name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_INVITATION.M6_FI_NO_DETAILS', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_INVITATION', 'Leaves out the date, time or place of the event.', '{"question":"What must an invitation include?","wrong_answer":"the reason only","correct_answer":"the event, date, time and place"}'::jsonb, 'The writer knows the details and forgets the reader does not.', 'Offer "the reason only" beside "the event, date, time and place" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check: what, when, what time, where.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_INVITATION.M6_FI_INFORMAL_TONE', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_INVITATION', 'Writes in a chatty, informal tone.', '{"question":"Which suits a letter to the chief?","wrong_answer":"Hi Chief! Come to our party, it will be fun.","correct_answer":"We kindly invite you to our prize-giving day."}'::jsonb, 'Friendly letter habits.', 'Offer "Hi Chief! Come to our party, it will be fun." beside "We kindly invite you to our prize-giving day." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Formal letters use polite, formal words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_INVITATION.M6_FI_ONE_ADDRESS', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_INVITATION', 'Writes only one address.', '{"question":"How many addresses in a formal letter?","wrong_answer":"one","correct_answer":"two: the writer''s and the receiver''s"}'::jsonb, 'Friendly letter layout is reused.', 'Offer "one" beside "two: the writer''s and the receiver''s" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add the receiver''s address on the left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_INVITATION.M6_FI_NO_RSVP', 'ENGL.G6.WRITIN.T4_FUNCTIONAL_WRITING.FORMAL_INVITATION', 'Does not ask the guest to reply.', '{"question":"What should the last paragraph ask?","wrong_answer":"nothing","correct_answer":"that the guest confirms attendance"}'::jsonb, 'The purpose of a reply is not known.', 'Offer "nothing" beside "that the guest confirms attendance" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask politely for a reply by a date.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.ORAL_RESPONSE.M6_OR_ONE_WORD', 'ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.ORAL_RESPONSE', 'Answers an oral question with one word.', '{"question":"Where is the Maasai Mara?","wrong_answer":"Narok.","correct_answer":"The Maasai Mara is in Narok County."}'::jsonb, 'Classroom habit of short answers.', 'Offer "Narok." beside "The Maasai Mara is in Narok County." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Answer in a full sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.ORAL_RESPONSE.M6_OR_OFF_QUESTION', 'ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.ORAL_RESPONSE', 'Answers a different question from the one asked.', '{"question":"When is the best time to see the migration?","wrong_answer":"There are many lions.","correct_answer":"Between July and October."}'::jsonb, 'The child talks about what he or she remembers.', 'Offer "There are many lions." beside "Between July and October." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for the question word: when wants a time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.ORAL_RESPONSE.M6_OR_DETAIL_WRONG', 'ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.ORAL_RESPONSE', 'Gives a detail that was not in the talk.', '{"question":"How much is the park fee for children? (talk said 200 shillings)","wrong_answer":"500 shillings","correct_answer":"200 shillings"}'::jsonb, 'A guess replaces what was heard.', 'Offer "500 shillings" beside "200 shillings" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the number the speaker gave.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.ORAL_RESPONSE.M6_OR_NO_FOLLOW_UP', 'ENGL.G6.LISTEN.T5_PRONUNCIATION_AND_VO.ORAL_RESPONSE', 'Cannot ask a follow-up question.', '{"question":"Ask the guide one more question.","wrong_answer":"silence","correct_answer":"How many animals cross the river each year?"}'::jsonb, 'The child sees listening as only answering.', 'Offer "silence" beside "How many animals cross the river each year?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask about something the speaker mentioned.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T5_ADJECTIVES.ADJECTIVE_DEGREES.M_DEGR_AS_COMPARATIVE', 'ENGL.G6.LANGUA.T5_ADJECTIVES.ADJECTIVE_DEGREES', 'Uses the comparative inside as ... as (as taller as).', '{"question":"Kamau is as ___ as his brother.","wrong_answer":"taller","correct_answer":"tall"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "taller" next to the right answer in a new sentence and ask again.', 'Between as ... as use the plain adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T5_ADJECTIVES.ADJECTIVE_DEGREES.M_DEGR_SUPER_THAN', 'ENGL.G6.LANGUA.T5_ADJECTIVES.ADJECTIVE_DEGREES', 'Uses than with a superlative (the tallest than).', '{"question":"Wanjiru is the tallest girl ___ the class.","wrong_answer":"than","correct_answer":"in"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "than" next to the right answer in a new sentence and ask again.', 'Than goes with a comparative (taller than). With the tallest use in or of.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T5_ADJECTIVES.ADJECTIVE_DEGREES.M_DEGR_THE_MISSING', 'ENGL.G6.LANGUA.T5_ADJECTIVES.ADJECTIVE_DEGREES', 'Leaves out the before a superlative.', '{"question":"Otieno is ___ fastest runner in Grade 6.","wrong_answer":"(nothing)","correct_answer":"the"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "(nothing)" next to the right answer in a new sentence and ask again.', 'A superlative picks one from a group and needs the.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T5_ADJECTIVES.ADJECTIVE_DEGREES.M_DEGR_THAN_MISSING', 'ENGL.G6.LANGUA.T5_ADJECTIVES.ADJECTIVE_DEGREES', 'Leaves out than after a comparative (Juma is taller Peter).', '{"question":"Juma is taller ___ Peter.","wrong_answer":"from","correct_answer":"than"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "from" next to the right answer in a new sentence and ask again.', 'After a comparative the word is than.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T5_ADJECTIVES.ADJECTIVE_DEGREES.M_DEGR_ONE_OF_SINGULAR', 'ENGL.G6.LANGUA.T5_ADJECTIVES.ADJECTIVE_DEGREES', 'Writes one of the tallest girl instead of girls.', '{"question":"She is one of the tallest ___ in the school.","wrong_answer":"girl","correct_answer":"girls"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "girl" next to the right answer in a new sentence and ask again.', 'One of the ... needs a plural noun: there are many tallest girls and she is one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION.M6_NC_TENSE', 'ENGL.G6.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION', 'Switches tense in the story.', '{"question":"Correct: The cow escaped and runs into the forest.","wrong_answer":"escaped ... runs","correct_answer":"escaped ... ran"}'::jsonb, 'Present slips in at the exciting part.', 'Offer "escaped ... runs" beside "escaped ... ran" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the story in the past.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION.M6_NC_FLAT_ENDING', 'ENGL.G6.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION', 'Ends with "Then I woke up" or a sudden stop.', '{"question":"Better ending for a rescue story?","wrong_answer":"Then I woke up and it was a dream.","correct_answer":"The calf was safe, and we learnt to fence the river."}'::jsonb, 'A familiar ending is reused.', 'Offer "Then I woke up and it was a dream." beside "The calf was safe, and we learnt to fence the river." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'End by solving the problem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION.M6_NC_JUDGE_SPELLING_ONLY', 'ENGL.G6.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION', 'Judges a story only by spelling.', '{"question":"Mark this story with the checklist.","wrong_answer":"It has two spelling mistakes, so it is bad.","correct_answer":"Good plot and order; two spellings to fix."}'::jsonb, 'Correctness is the only thing noticed.', 'Offer "It has two spelling mistakes, so it is bad." beside "Good plot and order; two spellings to fix." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Judge language, relevance and organisation too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION.M6_NC_ABBREV_MISUSE', 'ENGL.G6.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION', 'Uses text-message short forms in a composition.', '{"question":"Is \"We went 2 the KWS office\" right in a story?","wrong_answer":"Yes","correct_answer":"No: We went to the KWS office"}'::jsonb, 'Phone writing habits.', 'Offer "Yes" beside "No: We went to the KWS office" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use proper acronyms (KWS), not text-speak (2).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS.M_SND_SPELL_NOT_SOUND', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS', 'Chooses by spelling and not by sound (bear for near).', '{"question":"Which word has the same vowel sound as \"near\"?","wrong_answer":"bear","correct_answer":"beer"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "bear" next to the right answer in a new sentence and ask again.', 'Say both words aloud. Do they sound alike?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS.M_SND_F_V', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS', 'Mixes /f/ and /v/ (fan and van).', '{"question":"Which word starts with the sound /v/?","wrong_answer":"fan","correct_answer":"van"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "fan" next to the right answer in a new sentence and ask again.', 'For /v/ the upper teeth touch the lower lip and the voice hums; for /f/ it does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS.M_SND_SILENT_H', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS', 'Says the h in hour and honest, or drops it in house.', '{"question":"Which word does NOT start with the sound /h/?","wrong_answer":"house","correct_answer":"hour"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "house" next to the right answer in a new sentence and ask again.', 'In hour, honest and heir the h is silent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS.M_SND_TOUR_MORE', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.SOUNDS', 'Treats /ʊə/ and /ɔː/ as one sound (tour, more).', '{"question":"Which word has the same vowel sound as \"tour\"?","wrong_answer":"more","correct_answer":"poor"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "more" next to the right answer in a new sentence and ask again.', 'Tour, poor and pure share one sound. More, door and floor share another.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.WORK_ETHICS_WORDS.M6_WE_PUNCTUAL_REGULAR', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.WORK_ETHICS_WORDS', 'Uses punctual to mean comes every day.', '{"question":"Juma always arrives at exactly eight. He is ...","wrong_answer":"regular","correct_answer":"punctual"}'::jsonb, 'Two words about attendance are mixed.', 'Offer "regular" beside "punctual" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Punctual means on time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.WORK_ETHICS_WORDS.M6_WE_SALARY_WAGE', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.WORK_ETHICS_WORDS', 'Mixes up salary and wages.', '{"question":"A teacher is paid every month. She earns a ...","wrong_answer":"wage","correct_answer":"salary"}'::jsonb, 'Both mean pay.', 'Offer "wage" beside "salary" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A salary is paid monthly; wages are often daily or weekly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.WORK_ETHICS_WORDS.M6_WE_INTEGRITY_INTELLIGENT', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.WORK_ETHICS_WORDS', 'Thinks integrity means being clever.', '{"question":"A worker who returns extra change has ...","wrong_answer":"intelligence","correct_answer":"integrity"}'::jsonb, 'Long abstract words sound alike.', 'Offer "intelligence" beside "integrity" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Integrity is being honest when no one is watching.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.WORK_ETHICS_WORDS.M6_WE_DILIGENT_DELIGHT', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.WORK_ETHICS_WORDS', 'Thinks diligent means happy.', '{"question":"A diligent farmer is one who ...","wrong_answer":"is always happy","correct_answer":"works hard and carefully"}'::jsonb, 'Diligent sounds like delight.', 'Offer "is always happy" beside "works hard and carefully" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Diligent means hard-working and careful.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M6_IN_EXCLAM_FLAT', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Says an exclamation in a flat voice.', '{"question":"Say: What a hard worker!","wrong_answer":"flat, like a statement","correct_answer":"high, strong start, falling at the end"}'::jsonb, 'Exclamations are read like statements.', 'Offer "flat, like a statement" beside "high, strong start, falling at the end" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start high and strong to show feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M6_IN_WH_RISE', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Raises the voice at the end of WH questions.', '{"question":"Say: Where does your father work?","wrong_answer":"rising at work","correct_answer":"falling at work"}'::jsonb, 'All questions are thought to rise.', 'Offer "rising at work" beside "falling at work" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'WH questions fall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M6_IN_YESNO_FLAT', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Keeps a yes or no question flat.', '{"question":"Say: Are you a nurse?","wrong_answer":"flat","correct_answer":"rising at nurse"}'::jsonb, 'The home language marks questions with a word.', 'Offer "flat" beside "rising at nurse" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Rise at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M6_IN_STATEMENT_UP', 'ENGL.G6.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Lets statements rise, sounding unsure.', '{"question":"Say: I want to be a pilot.","wrong_answer":"rising at pilot","correct_answer":"falling at pilot"}'::jsonb, 'Nervous speakers sound as if asking.', 'Offer "rising at pilot" beside "falling at pilot" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'End a statement low and firm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T6_INTENSIVE_READING.RELATE_TO_LIFE.M6_RL_RETELL', 'ENGL.G6.READIN.T6_INTENSIVE_READING.RELATE_TO_LIFE', 'Retells the text instead of linking it.', '{"question":"How is the story about a hard-working mechanic like your life?","wrong_answer":"The mechanic fixed the car.","correct_answer":"My uncle works hard at his garage every day."}'::jsonb, 'Retelling is easier than linking.', 'Offer "The mechanic fixed the car." beside "My uncle works hard at his garage every day." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say something from your own life.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T6_INTENSIVE_READING.RELATE_TO_LIFE.M6_RL_SURFACE', 'ENGL.G6.READIN.T6_INTENSIVE_READING.RELATE_TO_LIFE', 'Links on a surface detail.', '{"question":"Text: a girl saves money to start a business. Link?","wrong_answer":"I also wear a school uniform.","correct_answer":"I save my pocket money in a tin."}'::jsonb, 'Any shared detail seems enough.', 'Offer "I also wear a school uniform." beside "I save my pocket money in a tin." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Link the main idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T6_INTENSIVE_READING.RELATE_TO_LIFE.M6_RL_JUDGES_ONLY', 'ENGL.G6.READIN.T6_INTENSIVE_READING.RELATE_TO_LIFE', 'Only judges the character instead of relating.', '{"question":"Link the story to your life.","wrong_answer":"She is stupid.","correct_answer":"Like her, I once lost my way and asked for help."}'::jsonb, 'Judgement replaces connection.', 'Offer "She is stupid." beside "Like her, I once lost my way and asked for help." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tell when something like it happened to you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T6_INTENSIVE_READING.RELATE_TO_LIFE.M6_RL_CHANGES_TEXT', 'ENGL.G6.READIN.T6_INTENSIVE_READING.RELATE_TO_LIFE', 'Changes the text to fit the memory.', '{"question":"What did the boy in the text do with the money?","wrong_answer":"He bought sweets, like me.","correct_answer":"He gave it to his mother."}'::jsonb, 'Memory overwrites the text.', 'Offer "He bought sweets, like me." beside "He gave it to his mother." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep what the text says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.PHRASAL_QUANTIFIERS.M_PQ_NUMBER_UNCOUNT', 'ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.PHRASAL_QUANTIFIERS', 'Uses a number of with an uncountable noun (a number of water).', '{"question":"A number of ___ were late.","wrong_answer":"water","correct_answer":"learners"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "water" next to the right answer in a new sentence and ask again.', 'A number of needs things we can count.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.PHRASAL_QUANTIFIERS.M_PQ_AMOUNT_COUNT', 'ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.PHRASAL_QUANTIFIERS', 'Uses a great deal of or an amount of with countable nouns.', '{"question":"We used a great deal of ___ for the cake.","wrong_answer":"eggs","correct_answer":"flour"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "eggs" next to the right answer in a new sentence and ask again.', 'A great deal of is for things we cannot count one by one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.PHRASAL_QUANTIFIERS.M_PQ_PIECE_PLURAL', 'ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.PHRASAL_QUANTIFIERS', 'Adds -s to the uncountable noun (a piece of advices).', '{"question":"He gave me a piece of ___.","wrong_answer":"advices","correct_answer":"advice"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "advices" next to the right answer in a new sentence and ask again.', 'Advice, news and furniture never take -s. Count them with a piece of.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.PHRASAL_QUANTIFIERS.M_PQ_OF_MISSING', 'ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.PHRASAL_QUANTIFIERS', 'Leaves out of (a loaf bread).', '{"question":"Mama bought a loaf ___ bread.","wrong_answer":"(nothing)","correct_answer":"of"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "(nothing)" next to the right answer in a new sentence and ask again.', 'The pattern is a loaf OF bread, a bar OF soap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.PHRASAL_QUANTIFIERS.M_PQ_WRONG_UNIT', 'ENGL.G6.LANGUA.T6_PHRASAL_QUANTIFIERS.PHRASAL_QUANTIFIERS', 'Uses the wrong unit word (a loaf of soap, a bar of milk).', '{"question":"I bought a bar of ___.","wrong_answer":"milk","correct_answer":"soap"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "milk" next to the right answer in a new sentence and ask again.', 'Each thing has its own unit: loaf of bread, bar of soap, bottle of milk, piece of chalk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION.M6_PIC_LABELS', 'ENGL.G6.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION', 'Names what is in each picture instead of telling the story.', '{"question":"Picture: a mechanic under a car.","wrong_answer":"A man. A car.","correct_answer":"Mr Kipchoge, the mechanic, crawled under the matatu to fix it."}'::jsonb, 'Picture labelling from lower grades.', 'Offer "A man. A car." beside "Mr Kipchoge, the mechanic, crawled under the matatu to fix it." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tell what the people did and felt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION.M6_PIC_NO_LINKS', 'ENGL.G6.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION', 'Writes each picture as a separate part with no links.', '{"question":"How do you link picture 2 to 3?","wrong_answer":"no link","correct_answer":"Later that day, ..."}'::jsonb, 'Each picture is treated alone.', 'Offer "no link" beside "Later that day, ..." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use time and cause links.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION.M6_PIC_SKIP', 'ENGL.G6.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION', 'Skips a picture.', '{"question":"Six pictures: how many must the story cover?","wrong_answer":"five","correct_answer":"six"}'::jsonb, 'A hard picture is skipped.', 'Offer "five" beside "six" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tick each picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION.M6_PIC_TITLE', 'ENGL.G6.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION', 'Gives a title that does not fit all the pictures.', '{"question":"Pictures show a lazy worker who later becomes hard-working. Title?","wrong_answer":"The Car","correct_answer":"From Lazy to Diligent"}'::jsonb, 'The title is taken from the first picture.', 'Offer "The Car" beside "From Lazy to Diligent" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Name what the whole story is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T7_TENSE.FUTURE_CONTINUOUS.M_FC_NO_BE', 'ENGL.G6.LANGUA.T7_TENSE.FUTURE_CONTINUOUS', 'Leaves out be (will travelling).', '{"question":"This time tomorrow we ___ travelling to Kisumu.","wrong_answer":"will","correct_answer":"will be"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "will" next to the right answer in a new sentence and ask again.', 'The future continuous is will + be + verb-ing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T7_TENSE.FUTURE_CONTINUOUS.M_FC_WILL_BEEN', 'ENGL.G6.LANGUA.T7_TENSE.FUTURE_CONTINUOUS', 'Writes will been or will being.', '{"question":"At six o''clock I ___ cooking supper.","wrong_answer":"will been","correct_answer":"will be"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "will been" next to the right answer in a new sentence and ask again.', 'After will, the verb be stays in its plain form: will be.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T7_TENSE.FUTURE_CONTINUOUS.M_FC_PRESENT', 'ENGL.G6.LANGUA.T7_TENSE.FUTURE_CONTINUOUS', 'Uses the present continuous for a future time (is travelling tomorrow at noon).', '{"question":"At noon tomorrow Mama ___ working in the shamba.","wrong_answer":"is","correct_answer":"will be"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "is" next to the right answer in a new sentence and ask again.', 'A future time word asks for will be.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T7_TENSE.FUTURE_CONTINUOUS.M_FC_NO_ING', 'ENGL.G6.LANGUA.T7_TENSE.FUTURE_CONTINUOUS', 'Writes will be with the plain verb (will be travel).', '{"question":"Tomorrow at ten the pupils ___ writing a test.","wrong_answer":"will write","correct_answer":"will be"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "will write" next to the right answer in a new sentence and ask again.', 'The pattern is will be + verb-ing, a continuing action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.COMMA_USE.M_COMMA_SUBJECT_VERB', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.COMMA_USE', 'Puts a comma between a subject and its verb.', '{"question":"Which sentence is correct?","wrong_answer":"The boy in the blue shirt, is my cousin.","correct_answer":"The boy in the blue shirt is my cousin."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "The boy in the blue shirt, is my cousin." next to the right answer in a new sentence and ask again.', 'Read it: a comma does not come between who and what they do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.COMMA_USE.M6_COMMA_LIST_MISSING', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.COMMA_USE', 'Leaves out the commas in a list.', '{"question":"Which sentence is correct?","wrong_answer":"Mama bought rice beans maize and sugar.","correct_answer":"Mama bought rice, beans, maize and sugar."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Mama bought rice beans maize and sugar." next to the right answer in a new sentence and ask again.', 'Put a comma after every item except the last two joined by and.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.COMMA_USE.M_COMMA_OPENING_MISSING', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.COMMA_USE', 'Leaves out the comma after an opening word or phrase.', '{"question":"Which sentence is correct?","wrong_answer":"After lunch we played football.","correct_answer":"After lunch, we played football."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "After lunch we played football." next to the right answer in a new sentence and ask again.', 'A phrase at the start of the sentence is followed by a comma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.COMMA_USE.M6_COMMA_SPLICE', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.COMMA_USE', 'Joins two full sentences with only a comma.', '{"question":"Which sentence is correct?","wrong_answer":"It was raining, we stayed at home.","correct_answer":"It was raining, so we stayed at home."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "It was raining, we stayed at home." next to the right answer in a new sentence and ask again.', 'Two sentences need a full stop or a joining word as well as the comma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.COMMA_USE.M_COMMA_SPEECH_MISSING', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.COMMA_USE', 'Leaves out the comma that separates the speaker from the words.', '{"question":"Which sentence is correct?","wrong_answer":"Mama said \"Come and eat.\"","correct_answer":"Mama said, \"Come and eat.\""}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Mama said "Come and eat."" next to the right answer in a new sentence and ask again.', 'A comma goes between said and the opening quotation mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.QUOTATION_MARKS.M_QM_MISSING', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.QUOTATION_MARKS', 'Writes direct speech with no quotation marks.', '{"question":"Which sentence is correct?","wrong_answer":"Mama said, Come and eat.","correct_answer":"Mama said, \"Come and eat.\""}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Mama said, Come and eat." next to the right answer in a new sentence and ask again.', 'The exact words spoken go inside double quotation marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.QUOTATION_MARKS.M_QM_PUNCT_OUTSIDE', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.QUOTATION_MARKS', 'Puts the full stop or question mark outside the closing marks.', '{"question":"Which sentence is correct?","wrong_answer":"Juma asked, \"Where is my bag?\".","correct_answer":"Juma asked, \"Where is my bag?\""}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Juma asked, "Where is my bag?"." next to the right answer in a new sentence and ask again.', 'The mark that ends the speech goes inside the quotation marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.QUOTATION_MARKS.M_QM_CAPITAL_SPLIT', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.QUOTATION_MARKS', 'Starts the second part of split speech with a capital letter.', '{"question":"Which sentence is correct?","wrong_answer":"\"I am tired,\" said Amina, \"But I will finish.\"","correct_answer":"\"I am tired,\" said Amina, \"but I will finish.\""}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer ""I am tired," said Amina, "But I will finish."" next to the right answer in a new sentence and ask again.', 'It is one sentence cut in two. The second part has a small letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.QUOTATION_MARKS.M_QM_REPORTED', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.QUOTATION_MARKS', 'Puts quotation marks round reported speech.', '{"question":"Which sentence is correct?","wrong_answer":"She said that \"she was tired.\"","correct_answer":"She said that she was tired."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "She said that "she was tired."" next to the right answer in a new sentence and ask again.', 'Quotation marks are for the exact words only. Reported speech is not exact.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.QUOTATION_MARKS.M_QM_SINGLE', 'ENGL.G6.WRITIN.T7_MECHANICS_OF_WRITING.QUOTATION_MARKS', 'Uses single quotation marks where the design asks for double.', '{"question":"Which sentence is correct?","wrong_answer":"Mama said, ''Come and eat.''","correct_answer":"Mama said, \"Come and eat.\""}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Mama said, ''Come and eat.''" next to the right answer in a new sentence and ask again.', 'In your school use double quotation marks for speech.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.RIDDLES_PROVERBS.M_RID_PROVERB_AS_RIDDLE', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.RIDDLES_PROVERBS', 'Calls a proverb a riddle.', '{"question":"Which of these is a riddle?","wrong_answer":"Slow and steady wins the race.","correct_answer":"What has a neck but no head?"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Slow and steady wins the race." next to the right answer in a new sentence and ask again.', 'A riddle asks a question and waits for an answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.RIDDLES_PROVERBS.M_RID_RIDDLE_AS_PROVERB', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.RIDDLES_PROVERBS', 'Calls a riddle a proverb.', '{"question":"Which of these is a proverb?","wrong_answer":"What runs but never walks?","correct_answer":"Honesty is the best policy."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "What runs but never walks?" next to the right answer in a new sentence and ask again.', 'A proverb tells us what to do or what is true.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.RIDDLES_PROVERBS.M_RID_LITERAL', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.RIDDLES_PROVERBS', 'Answers a riddle from the words and not the description.', '{"question":"I have a neck but no head. What am I?","wrong_answer":"a giraffe","correct_answer":"a bottle"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a giraffe" next to the right answer in a new sentence and ask again.', 'Think: what has a neck but no head and a mouth?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.RIDDLES_PROVERBS.M_RID_NO_ANSWER', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.RIDDLES_PROVERBS', 'Thinks a riddle is just a story with no answer.', '{"question":"What is special about a riddle?","wrong_answer":"It tells a long story.","correct_answer":"It has a hidden answer to guess."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "It tells a long story." next to the right answer in a new sentence and ask again.', 'Riddles end with a puzzle: the listener answers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.PHRASAL_VERBS_USE.M_PV_LITERAL', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.PHRASAL_VERBS_USE', 'Reads a phrasal verb word for word.', '{"question":"What does \"put up with\" mean?","wrong_answer":"put something on top","correct_answer":"bear patiently"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "put something on top" next to the right answer in a new sentence and ask again.', 'The particle changes the verb''s meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.PHRASAL_VERBS_USE.M_PV_PARTICLE', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.PHRASAL_VERBS_USE', 'Uses the wrong particle (give in for give up).', '{"question":"He did not ___ trying until he passed.","wrong_answer":"give in","correct_answer":"give up"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "give in" next to the right answer in a new sentence and ask again.', 'Give up: stop trying. Give in: say yes after refusing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.PHRASAL_VERBS_USE.M_PV_PREP', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.PHRASAL_VERBS_USE', 'Uses the wrong preposition after the phrasal verb (agree to, cope in).', '{"question":"I agree ___ you.","wrong_answer":"to","correct_answer":"with"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "to" next to the right answer in a new sentence and ask again.', 'Agree with a person. Cope with a problem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.PHRASAL_VERBS_USE.M_PV_SAME_MEANING', 'ENGL.G6.LISTEN.T8_PRONUNCIATION_AND_VO.PHRASAL_VERBS_USE', 'Thinks break down and break up mean the same.', '{"question":"The old matatu ___ on the way to Nairobi.","wrong_answer":"broke up","correct_answer":"broke down"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "broke up" next to the right answer in a new sentence and ask again.', 'Broke down: stopped working. Broke up: split apart or ended.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T8_FLUENCY.READ_FLUENTLY.M6_RF_NO_PHRASING', 'ENGL.G6.READIN.T8_FLUENCY.READ_FLUENTLY', 'Reads word by word.', '{"question":"Read: The vet checked the calf and gave it an injection.","wrong_answer":"The. vet. checked.","correct_answer":"The vet checked the calf / and gave it an injection."}'::jsonb, 'Decoding takes all the attention.', 'Offer "The. vet. checked." beside "The vet checked the calf / and gave it an injection." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read in phrases.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T8_FLUENCY.READ_FLUENTLY.M6_RF_TOO_FAST', 'ENGL.G6.READIN.T8_FLUENCY.READ_FLUENTLY', 'Reads too fast and skips words.', '{"question":"Read the paragraph about the farm.","wrong_answer":"rushes and drops small words","correct_answer":"steady talking speed"}'::jsonb, 'Speed is thought to be fluency.', 'Offer "rushes and drops small words" beside "steady talking speed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read at talking speed; every word counts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T8_FLUENCY.READ_FLUENTLY.M6_RF_FLAT_SPEECH', 'ENGL.G6.READIN.T8_FLUENCY.READ_FLUENTLY', 'Reads speech with no change of voice.', '{"question":"Read: \"Help! The cow is stuck!\" shouted Juma.","wrong_answer":"flat","correct_answer":"urgent, loud voice"}'::jsonb, 'Expression is not linked to meaning.', 'Offer "flat" beside "urgent, loud voice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Let the voice show the shout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T8_FLUENCY.READ_FLUENTLY.M6_RF_SELF_CORRECT_LOOP', 'ENGL.G6.READIN.T8_FLUENCY.READ_FLUENTLY', 'Repeats every line to correct one slip.', '{"question":"You misread one word. What do you do?","wrong_answer":"start the whole line again","correct_answer":"correct the word and go on"}'::jsonb, 'Fear of mistakes.', 'Offer "start the whole line again" beside "correct the word and go on" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Fix the word and keep going.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.ACTIVE_PASSIVE.M_PASS_NO_BE', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.ACTIVE_PASSIVE', 'Leaves out be in a passive sentence (The window broken by the wind).', '{"question":"The window ___ by the wind.","wrong_answer":"broken","correct_answer":"was broken"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "broken" next to the right answer in a new sentence and ask again.', 'A passive needs be + the past participle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.ACTIVE_PASSIVE.M_PASS_PAST_FORM', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.ACTIVE_PASSIVE', 'Uses the simple past instead of the past participle (was wrote, was ate).', '{"question":"The letter was ___ by Mary.","wrong_answer":"wrote","correct_answer":"written"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "wrote" next to the right answer in a new sentence and ask again.', 'After was or were use the participle: written, eaten, broken, taken.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.ACTIVE_PASSIVE.M_PASS_AGREEMENT', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.ACTIVE_PASSIVE', 'Does not match was or were to the subject (The books was returned).', '{"question":"The books ___ returned on Friday.","wrong_answer":"was","correct_answer":"were"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "was" next to the right answer in a new sentence and ask again.', 'The subject is plural, so use were.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.ACTIVE_PASSIVE.M_PASS_ACTIVE_AS_PASSIVE', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.ACTIVE_PASSIVE', 'Calls an active sentence passive because it is in the past.', '{"question":"Which sentence is passive?","wrong_answer":"Wanjiku cooked the rice.","correct_answer":"The rice was cooked by Wanjiku."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Wanjiku cooked the rice." next to the right answer in a new sentence and ask again.', 'Ask: does the subject do the action or receive it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.ACTIVE_PASSIVE.M_PASS_DOER_SUBJECT', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.ACTIVE_PASSIVE', 'Turns the sentence round but keeps the doer as the subject.', '{"question":"Passive of: Baraka kicked the ball.","wrong_answer":"Baraka was kicked by the ball.","correct_answer":"The ball was kicked by Baraka."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Baraka was kicked by the ball." next to the right answer in a new sentence and ask again.', 'The thing acted on moves to the front.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS.M_CW_SAY_TELL', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS', 'Uses say and tell for each other (She said me; He told that).', '{"question":"The teacher ___ us a story.","wrong_answer":"said","correct_answer":"told"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "said" next to the right answer in a new sentence and ask again.', 'Tell takes a person straight after it (tell us). Say does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS.M_CW_BORROW_LEND', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS', 'Uses borrow and lend for each other.', '{"question":"Please ___ me your pen.","wrong_answer":"borrow","correct_answer":"lend"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "borrow" next to the right answer in a new sentence and ask again.', 'Lend: you give it for a short time. Borrow: you take it for a short time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS.M_CW_BRING_TAKE', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS', 'Uses bring and take for each other.', '{"question":"Please ___ this letter to the headteacher''s office.","wrong_answer":"bring","correct_answer":"take"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "bring" next to the right answer in a new sentence and ask again.', 'Bring: towards the speaker. Take: away from the speaker.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS.M_CW_LEARN_TEACH', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS', 'Uses learn and teach for each other.', '{"question":"Mr Kimani will ___ us fractions.","wrong_answer":"learn","correct_answer":"teach"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "learn" next to the right answer in a new sentence and ask again.', 'The teacher teaches. The pupil learns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS.M_CW_HEAR_LISTEN', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS', 'Uses hear and listen for each other.', '{"question":"Please ___ carefully to the story.","wrong_answer":"hear","correct_answer":"listen"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "hear" next to the right answer in a new sentence and ask again.', 'Listen: you try to hear. Hear: it reaches your ears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS.M_CW_SEE_LOOK', 'ENGL.G6.LANGUA.T8_SENTENCE_PATTERNS.CONFUSED_WORDS', 'Uses see, look and watch for each other.', '{"question":"___ at the bird on the roof.","wrong_answer":"See","correct_answer":"Look"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "See" next to the right answer in a new sentence and ask again.', 'Look is on purpose, and it takes at. See is what your eyes find.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.SPEAK_FLUENTLY.M6_SF_READS_SPEECH', 'ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.SPEAK_FLUENTLY', 'Reads the speech word for word, eyes down.', '{"question":"Give your speech on lifestyle diseases.","wrong_answer":"reads every word with head down","correct_answer":"speaks from key points, looking up"}'::jsonb, 'Fear of forgetting.', 'Offer "reads every word with head down" beside "speaks from key points, looking up" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write key points; look at the audience.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.SPEAK_FLUENTLY.M6_SF_FILLERS', 'ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.SPEAK_FLUENTLY', 'Fills pauses with eeh, aah or "you know".', '{"question":"Talk about healthy eating.","wrong_answer":"Eeh, you know, we should, aah ...","correct_answer":"We should eat more vegetables."}'::jsonb, 'Thinking aloud.', 'Offer "Eeh, you know, we should, aah ..." beside "We should eat more vegetables." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pause silently.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.SPEAK_FLUENTLY.M6_SF_RUSH', 'ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.SPEAK_FLUENTLY', 'Rushes through the talk.', '{"question":"How long should a two-minute talk take?","wrong_answer":"thirty seconds","correct_answer":"about two minutes"}'::jsonb, 'Nerves.', 'Offer "thirty seconds" beside "about two minutes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Slow down and pause between points.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.SPEAK_FLUENTLY.M6_SF_NO_STRUCTURE', 'ENGL.G6.LISTEN.T9_PRONUNCIATION_AND_SP.SPEAK_FLUENTLY', 'Gives points in no order with no opening or ending.', '{"question":"How should a speech begin?","wrong_answer":"with the first fact that comes to mind","correct_answer":"with a greeting and the topic"}'::jsonb, 'Speeches are not planned.', 'Offer "with the first fact that comes to mind" beside "with a greeting and the topic" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Greet, say the topic, give points, close.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T9_INTENSIVE_READING_FI.FACT_OPINION.M_FO_OPINION_AS_FACT', 'ENGL.G6.READIN.T9_INTENSIVE_READING_FI.FACT_OPINION', 'Takes an opinion as a fact.', '{"question":"Which is a fact?","wrong_answer":"Githeri is the best food.","correct_answer":"Githeri is made from maize and beans."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Githeri is the best food." next to the right answer in a new sentence and ask again.', 'A fact can be checked. Words like best, nicest and should show an opinion.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T9_INTENSIVE_READING_FI.FACT_OPINION.M_FO_FACT_AS_OPINION', 'ENGL.G6.READIN.T9_INTENSIVE_READING_FI.FACT_OPINION', 'Takes a fact as an opinion.', '{"question":"Which is an opinion?","wrong_answer":"Nairobi is the capital of Kenya.","correct_answer":"Nairobi is the most exciting city."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Nairobi is the capital of Kenya." next to the right answer in a new sentence and ask again.', 'Can you check it? Then it is a fact.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T9_INTENSIVE_READING_FI.FACT_OPINION.M_FO_STORY_INFO', 'ENGL.G6.READIN.T9_INTENSIVE_READING_FI.FACT_OPINION', 'Calls a made-up story information.', '{"question":"Is this text a story or information?","wrong_answer":"information","correct_answer":"a story"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "information" next to the right answer in a new sentence and ask again.', 'A story has made-up characters and events.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T9_INTENSIVE_READING_FI.FACT_OPINION.M6_FO_NUMBER_FACT', 'ENGL.G6.READIN.T9_INTENSIVE_READING_FI.FACT_OPINION', 'Thinks any sentence with a number is a fact.', '{"question":"\"Ninety per cent of people love tea.\" Fact or opinion?","wrong_answer":"fact","correct_answer":"opinion (unless it can be checked)"}'::jsonb, 'Numbers look official.', 'Offer "fact" beside "opinion (unless it can be checked)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A fact can be checked; a feeling about many people is still an opinion.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T9_ADVERBS.ADVERBS_USE.M6_ADV_ADJ_FOR_ADV', 'ENGL.G6.LANGUA.T9_ADVERBS.ADVERBS_USE', 'Uses an adjective after an action verb (He runs quick).', '{"question":"The boy runs ___.","wrong_answer":"quick","correct_answer":"quickly"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "quick" next to the right answer in a new sentence and ask again.', 'How does he run? An -ly word tells how.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T9_ADVERBS.ADVERBS_USE.M6_ADV_GOOD_WELL', 'ENGL.G6.LANGUA.T9_ADVERBS.ADVERBS_USE', 'Writes good where well is needed (She sings good).', '{"question":"Wanjiru sings very ___.","wrong_answer":"good","correct_answer":"well"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "good" next to the right answer in a new sentence and ask again.', 'Good describes a noun (a good song). Well describes a verb (sings well).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T9_ADVERBS.ADVERBS_USE.M6_ADV_HARD_HARDLY', 'ENGL.G6.LANGUA.T9_ADVERBS.ADVERBS_USE', 'Thinks hardly means with great effort.', '{"question":"He worked ___ and passed the exam.","wrong_answer":"hardly","correct_answer":"hard"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "hardly" next to the right answer in a new sentence and ask again.', 'Hard means with effort. Hardly means almost not at all.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T9_ADVERBS.ADVERBS_USE.M6_ADV_POSITION', 'ENGL.G6.LANGUA.T9_ADVERBS.ADVERBS_USE', 'Puts a frequency adverb in the wrong place (He goes always).', '{"question":"Juma ___ walks to school.","wrong_answer":"walks always","correct_answer":"always walks"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "walks always" next to the right answer in a new sentence and ask again.', 'Always, never, often and usually go before the main verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T9_ADVERBS.ADVERBS_USE.M_ADV_KIND_MIXED', 'ENGL.G6.LANGUA.T9_ADVERBS.ADVERBS_USE', 'Names the wrong kind of adverb (calls yesterday an adverb of place).', '{"question":"What does the adverb \"yesterday\" tell us?","wrong_answer":"place","correct_answer":"time"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "place" next to the right answer in a new sentence and ask again.', 'Ask: how, when, where or how often?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.HYPHENS.M_HYP_MISSING', 'ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.HYPHENS', 'Leaves out the hyphen in a compound before a noun (a well known singer).', '{"question":"Which sentence is correct?","wrong_answer":"She is a well known singer.","correct_answer":"She is a well-known singer."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "She is a well known singer." next to the right answer in a new sentence and ask again.', 'Two words that work as one describing word before a noun take a hyphen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.HYPHENS.M_HYP_NUMBER', 'ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.HYPHENS', 'Writes twenty one or twentyone.', '{"question":"Which is correct?","wrong_answer":"twenty one","correct_answer":"twenty-one"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "twenty one" next to the right answer in a new sentence and ask again.', 'The numbers 21 to 99 in words take a hyphen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.HYPHENS.M_HYP_PLURAL_COMPOUND', 'ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.HYPHENS', 'Makes the number plural inside a compound (a ten-years-old boy).', '{"question":"Which sentence is correct?","wrong_answer":"He is a ten-years-old boy.","correct_answer":"He is a ten-year-old boy."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "He is a ten-years-old boy." next to the right answer in a new sentence and ask again.', 'In a compound before a noun, the unit stays singular.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.HYPHENS.M_HYP_RELATIVE', 'ENGL.G6.WRITIN.T9_MECHANICS_OF_WRITING.HYPHENS', 'Writes mother in law or motherinlaw for mother-in-law.', '{"question":"Which is correct?","wrong_answer":"mother in law","correct_answer":"mother-in-law"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "mother in law" next to the right answer in a new sentence and ask again.', 'Words for relations by marriage are hyphenated.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.EXPRESS_MOODS.M6_EM_FLAT', 'ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.EXPRESS_MOODS', 'Uses one flat tone whatever the mood.', '{"question":"Your friend says she won a prize. Reply with feeling.","wrong_answer":"Okay. (flat)","correct_answer":"Wow, congratulations!"}'::jsonb, 'Emotion in speech is not practised.', 'Offer "Okay. (flat)" beside "Wow, congratulations!" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Let your voice show the feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.EXPRESS_MOODS.M6_EM_WRONG_MOOD', 'ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.EXPRESS_MOODS', 'Shows a mood that does not fit.', '{"question":"A friend says his grandmother is sick. You ...","wrong_answer":"laugh nervously","correct_answer":"say \"I am sorry to hear that\" softly"}'::jsonb, 'Nervous laughter.', 'Offer "laugh nervously" beside "say "I am sorry to hear that" softly" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match your tone to their news.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.EXPRESS_MOODS.M6_EM_WORDS_ONLY', 'ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.EXPRESS_MOODS', 'Says the right words in a tone that contradicts them.', '{"question":"Say \"I am sorry\" so it sounds sorry.","wrong_answer":"I am sorry. (angry voice)","correct_answer":"I am sorry. (soft, slow voice)"}'::jsonb, 'Words are thought to be enough.', 'Offer "I am sorry. (angry voice)" beside "I am sorry. (soft, slow voice)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The tone must match the words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.EXPRESS_MOODS.M6_EM_SURPRISE', 'ENGL.G6.LISTEN.T10_PRONUNCIATION_AND_VO.EXPRESS_MOODS', 'Cannot show surprise politely.', '{"question":"Your friend says the trip is cancelled. Show surprise.","wrong_answer":"You are lying!","correct_answer":"Really? I did not know that!"}'::jsonb, 'Surprise comes out as accusation.', 'Offer "You are lying!" beside "Really? I did not know that!" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Really? or Oh, no! show surprise politely.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T10_CONJUNCTIONS.CONJUNCTIONS_USE.M_CJ_ALTHOUGH_BUT', 'ENGL.G6.LANGUA.T10_CONJUNCTIONS.CONJUNCTIONS_USE', 'Uses although and but in the same sentence.', '{"question":"Choose: Although it rained, ___ we played outside. (but / nothing)","wrong_answer":"but","correct_answer":"nothing (Although it rained, we played outside.)"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "but" next to the right answer in a new sentence and ask again.', 'Use one joining word only: although OR but.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T10_CONJUNCTIONS.CONJUNCTIONS_USE.M_CJ_UNLESS_NOT', 'ENGL.G6.LANGUA.T10_CONJUNCTIONS.CONJUNCTIONS_USE', 'Writes unless not.', '{"question":"You will not pass ___ you study.","wrong_answer":"unless not","correct_answer":"unless"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "unless not" next to the right answer in a new sentence and ask again.', 'Unless already means if not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T10_CONJUNCTIONS.CONJUNCTIONS_USE.M_CJ_WHILE_UNTIL', 'ENGL.G6.LANGUA.T10_CONJUNCTIONS.CONJUNCTIONS_USE', 'Uses while or until where the meaning needs the other.', '{"question":"Wait here ___ I come back.","wrong_answer":"while","correct_answer":"until"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "while" next to the right answer in a new sentence and ask again.', 'Until: up to the time that. While: at the same time as.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T10_CONJUNCTIONS.CONJUNCTIONS_USE.M_CJ_SO_THAT_MEANING', 'ENGL.G6.LANGUA.T10_CONJUNCTIONS.CONJUNCTIONS_USE', 'Uses so that for a reason that already happened.', '{"question":"We left early ___ we could catch the bus.","wrong_answer":"because","correct_answer":"so that"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "because" next to the right answer in a new sentence and ask again.', 'So that tells the purpose: what you want to happen next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T10_CONJUNCTIONS.CONJUNCTIONS_USE.M_CJ_WHEREAS', 'ENGL.G6.LANGUA.T10_CONJUNCTIONS.CONJUNCTIONS_USE', 'Uses because or so where a contrast is meant (whereas).', '{"question":"Kamau likes tea, ___ his sister prefers milk.","wrong_answer":"because","correct_answer":"whereas"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "because" next to the right answer in a new sentence and ask again.', 'Two different things side by side: whereas.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIBING_WORDS.M6_DW_VAGUE', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIBING_WORDS', 'Uses vague adjectives (nice, good, big).', '{"question":"Improve: a nice beach","wrong_answer":"a nice beach","correct_answer":"a sandy, sunny beach"}'::jsonb, 'A small stock of adjectives.', 'Offer "a nice beach" beside "a sandy, sunny beach" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose a word for a sense: sandy, sunny, quiet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIBING_WORDS.M6_DW_ORDER', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIBING_WORDS', 'Puts adjectives in the wrong order.', '{"question":"a ___ ___ ___ basket (woven, small, old)","wrong_answer":"woven old small","correct_answer":"small old woven"}'::jsonb, 'Adjective order rules are not fixed.', 'Offer "woven old small" beside "small old woven" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Size, age, then material.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIBING_WORDS.M6_DW_ADVERB', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIBING_WORDS', 'Uses an adverb where an adjective is needed.', '{"question":"The park is ___ (quiet).","wrong_answer":"quietly","correct_answer":"quiet"}'::jsonb, 'The -ly ending is overused.', 'Offer "quietly" beside "quiet" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After is, describe the noun: quiet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIBING_WORDS.M6_DW_WRONG_SENSE', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIBING_WORDS', 'Uses an adjective that does not fit the thing.', '{"question":"Which fits \"the singing of birds\"?","wrong_answer":"colourful","correct_answer":"cheerful"}'::jsonb, 'Adjectives are not matched to the sense.', 'Offer "colourful" beside "cheerful" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sound words for sounds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION.M6_DC_STORY', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION', 'Writes a story instead of a description.', '{"question":"Describe the park you visit on Sundays.","wrong_answer":"One Sunday we went and a monkey stole my bag.","correct_answer":"The park is green and shady, with benches under jacaranda trees."}'::jsonb, 'Narrative is the most practised.', 'Offer "One Sunday we went and a monkey stole my bag." beside "The park is green and shady, with benches under jacaranda trees." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Describe what it is like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION.M6_DC_LIST', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION', 'Lists objects with no description.', '{"question":"Improve: There are trees, benches, a pond.","wrong_answer":"There are trees, benches, a pond.","correct_answer":"Tall trees shade old wooden benches beside a still pond."}'::jsonb, 'Naming is mistaken for describing.', 'Offer "There are trees, benches, a pond." beside "Tall trees shade old wooden benches beside a still pond." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add what each thing looks, sounds or feels like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION.M6_DC_NO_ORDER', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION', 'Jumps around the place.', '{"question":"Which order is clearer?","wrong_answer":"gate, pond, gate, trees","correct_answer":"from the gate, past the trees, to the pond"}'::jsonb, 'Details come as remembered.', 'Offer "gate, pond, gate, trees" beside "from the gate, past the trees, to the pond" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Move in one direction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION.M6_DC_JUDGE_LENGTH', 'ENGL.G6.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION', 'Judges a description only by how long it is.', '{"question":"Which description is better?","wrong_answer":"the longest one","correct_answer":"the one with exact words and a clear order"}'::jsonb, 'Length is mistaken for quality.', 'Offer "the longest one" beside "the one with exact words and a clear order" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Judge words, relevance, creativity and order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T11_INTERROGATIVES.INTERROGATIVES_USE.M_Q_WHO_WHOSE', 'ENGL.G6.LANGUA.T11_INTERROGATIVES.INTERROGATIVES_USE', 'Uses who where whose (belonging) is asked.', '{"question":"___ bag is this?","wrong_answer":"Who","correct_answer":"Whose"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Who" next to the right answer in a new sentence and ask again.', 'The answer is an owner: Wanjiru''s. That is whose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T11_INTERROGATIVES.INTERROGATIVES_USE.M_Q_WHAT_WHICH', 'ENGL.G6.LANGUA.T11_INTERROGATIVES.INTERROGATIVES_USE', 'Uses what where which is needed for a choice from a small set.', '{"question":"___ of these two books is yours?","wrong_answer":"What","correct_answer":"Which"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "What" next to the right answer in a new sentence and ask again.', 'Which is for a choice from a small number you can see.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T11_INTERROGATIVES.INTERROGATIVES_USE.M_Q_HOWMUCH_MANY', 'ENGL.G6.LANGUA.T11_INTERROGATIVES.INTERROGATIVES_USE', 'Uses how much for things you can count, or how many for things you cannot.', '{"question":"How ___ eggs did you buy?","wrong_answer":"much","correct_answer":"many"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "much" next to the right answer in a new sentence and ask again.', 'Count them? how many. Cannot count them? how much.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T11_INTERROGATIVES.INTERROGATIVES_USE.M_Q_HOWLONG_HOWFAR', 'ENGL.G6.LANGUA.T11_INTERROGATIVES.INTERROGATIVES_USE', 'Mixes how long (time) with how far (distance).', '{"question":"___ is it from Nakuru to Naivasha?","wrong_answer":"How long","correct_answer":"How far"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "How long" next to the right answer in a new sentence and ask again.', 'Distance is how far. How long can be time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T11_INTERROGATIVES.INTERROGATIVES_USE.M_Q_WHEN_HOWOFTEN', 'ENGL.G6.LANGUA.T11_INTERROGATIVES.INTERROGATIVES_USE', 'Uses when where how often is asked.', '{"question":"___ do you go to the library? Twice a week.","wrong_answer":"When","correct_answer":"How often"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "When" next to the right answer in a new sentence and ask again.', 'Twice a week tells how many times. That is how often.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING.SYNONYMS_ANTONYMS.M_SA_SYN_FOR_ANT', 'ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING.SYNONYMS_ANTONYMS', 'Gives a word with the same meaning when the opposite is asked.', '{"question":"The old man was weak but his son was ___.","wrong_answer":"feeble","correct_answer":"strong"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "feeble" next to the right answer in a new sentence and ask again.', 'Antonym means opposite. Ask: is it the same meaning or the opposite?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING.SYNONYMS_ANTONYMS.M_SA_ANT_FOR_SYN', 'ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING.SYNONYMS_ANTONYMS', 'Gives an opposite when a word with the same meaning is asked.', '{"question":"Wafula was delighted with his gift. He was very ___.","wrong_answer":"sad","correct_answer":"happy"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "sad" next to the right answer in a new sentence and ask again.', 'Synonym means same meaning. Delighted means very pleased.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING.SYNONYMS_ANTONYMS.M_SA_RELATED_NOT_PAIR', 'ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING.SYNONYMS_ANTONYMS', 'Gives a related word that is neither the same nor the opposite.', '{"question":"The road was wide but the path was ___.","wrong_answer":"long","correct_answer":"narrow"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "long" next to the right answer in a new sentence and ask again.', 'Think of the exact opposite of wide, not any word about roads.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING.SYNONYMS_ANTONYMS.M_SA_REPEAT', 'ENGL.G6.WRITIN.T11_MECHANICS_OF_WRITING.SYNONYMS_ANTONYMS', 'Repeats the same word as the answer.', '{"question":"The soup was hot, but the juice was ___.","wrong_answer":"hot","correct_answer":"cold"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "hot" next to the right answer in a new sentence and ask again.', 'The answer must be a different word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.NONVERBAL_CUES.M6_NC_NO_EYE_CONTACT', 'ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.NONVERBAL_CUES', 'Thinks a good speaker looks only at the floor or the paper.', '{"question":"Where should a speaker look?","wrong_answer":"at the floor","correct_answer":"at the audience, round the room"}'::jsonb, 'Looking down may be respectful at home.', 'Offer "at the floor" beside "at the audience, round the room" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In a speech, look at different people in the audience.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.NONVERBAL_CUES.M6_NC_GESTURE_MISMATCH', 'ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.NONVERBAL_CUES', 'Uses a gesture that does not fit the words.', '{"question":"A speaker says \"a tiny seed\" and spreads both arms wide. Is the cue right?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Gestures are added for show.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The gesture should match the meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.NONVERBAL_CUES.M6_NC_FIDGET', 'ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.NONVERBAL_CUES', 'Thinks fidgeting does not matter.', '{"question":"A speaker plays with a pen through the talk. Effect?","wrong_answer":"none","correct_answer":"it distracts the audience"}'::jsonb, 'The child does not notice his or her own movement.', 'Offer "none" beside "it distracts the audience" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep still hands unless you are gesturing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.NONVERBAL_CUES.M6_NC_FACE_WORDS', 'ENGL.G6.LISTEN.T12_PRONUNCIATION_AND_VO.NONVERBAL_CUES', 'Accepts a smiling face with sad news.', '{"question":"A speaker smiles while saying the forest has been destroyed. Fitting?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Smiling is thought always to be polite.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Your face should match the message.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T12_INTENSIVE_READING.POEM_FEATURES.M_POEM_SPELL_RHYME', 'ENGL.G6.READIN.T12_INTENSIVE_READING.POEM_FEATURES', 'Chooses words that end with the same letters but do not sound alike (cough, rough).', '{"question":"Which two words rhyme?","wrong_answer":"cough and rough","correct_answer":"rough and tough"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "cough and rough" next to the right answer in a new sentence and ask again.', 'Rhyme is sound, not spelling. Say the words aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T12_INTENSIVE_READING.POEM_FEATURES.M_POEM_REPEAT_RHYME', 'ENGL.G6.READIN.T12_INTENSIVE_READING.POEM_FEATURES', 'Takes repetition for rhyme.', '{"question":"Which line repeats in the poem?","wrong_answer":"the first line","correct_answer":"the line that appears again"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the first line" next to the right answer in a new sentence and ask again.', 'Repeated lines are the same words again, not just similar sounds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T12_INTENSIVE_READING.POEM_FEATURES.M_POEM_FIRST_WORD', 'ENGL.G6.READIN.T12_INTENSIVE_READING.POEM_FEATURES', 'Looks only at the first word of each line.', '{"question":"Which words rhyme?","wrong_answer":"the first words of lines","correct_answer":"the last words of lines"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the first words of lines" next to the right answer in a new sentence and ask again.', 'Rhymes are usually at the end of lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.READIN.T12_INTENSIVE_READING.POEM_FEATURES.M6_POEM_STANZA_LINE', 'ENGL.G6.READIN.T12_INTENSIVE_READING.POEM_FEATURES', 'Calls a line a stanza.', '{"question":"A group of lines with a space after it is a ...","wrong_answer":"line","correct_answer":"stanza"}'::jsonb, 'The two words are new together.', 'Offer "line" beside "stanza" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A stanza is a group of lines, like a paragraph in a poem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE.M_TAGS_SAME_SIGN', 'ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE', 'Uses a tag with the same sign as the statement (She is tall, is she?).', '{"question":"Wafula is a good singer, ___?","wrong_answer":"is he","correct_answer":"isn''t he"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "is he" next to the right answer in a new sentence and ask again.', 'A positive statement takes a negative tag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE.M_TAGS_ALWAYS_ISNTIT', 'ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE', 'Uses isn''t it for every sentence.', '{"question":"You can swim, ___?","wrong_answer":"isn''t it","correct_answer":"can''t you"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "isn''t it" next to the right answer in a new sentence and ask again.', 'Use the helper verb of the statement and a pronoun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE.M_TAGS_DO_FORM', 'ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE', 'Does not use do, does or did for a statement with no helper verb.', '{"question":"Otieno plays football, ___?","wrong_answer":"isn''t he","correct_answer":"doesn''t he"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "isn''t he" next to the right answer in a new sentence and ask again.', 'No helper verb? Bring in do, does or did.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE.M_TAGS_AM', 'ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE', 'Writes amn''t I or am not I after I am.', '{"question":"I am late, ___?","wrong_answer":"amn''t I","correct_answer":"aren''t I"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "amn''t I" next to the right answer in a new sentence and ask again.', 'After I am, the tag is aren''t I.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE.M_TAGS_NO_PRONOUN', 'ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE', 'Uses the noun again in the tag instead of a pronoun.', '{"question":"The girls are ready, ___?","wrong_answer":"aren''t the girls","correct_answer":"aren''t they"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "aren''t the girls" next to the right answer in a new sentence and ask again.', 'The tag always has a pronoun: he, she, it, they.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE.M_TAGS_NEG_NEG', 'ENGL.G6.LANGUA.T12_QUESTION_TAGS.QUESTION_TAGS_USE', 'Gives a negative tag to a negative statement.', '{"question":"You do not like beans, ___?","wrong_answer":"don''t you","correct_answer":"do you"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "don''t you" next to the right answer in a new sentence and ask again.', 'A negative statement takes a positive tag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.JOURNAL.M_JRN_THIRD_PERSON', 'ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.JOURNAL', 'Writes a journal in the third person (he, she) as if it were a story.', '{"question":"Which line could be from a journal?","wrong_answer":"Otieno went to the market.","correct_answer":"Today I went to the market."}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "Otieno went to the market." next to the right answer in a new sentence and ask again.', 'A journal is your own record, so you write I.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.JOURNAL.M_JRN_NO_DATE', 'ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.JOURNAL', 'Forgets the date at the top of an entry.', '{"question":"What should every journal entry begin with?","wrong_answer":"a greeting","correct_answer":"the date"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "a greeting" next to the right answer in a new sentence and ask again.', 'Each entry is for one day, so the date comes first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.JOURNAL.M_JRN_LETTER_FORM', 'ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.JOURNAL', 'Adds a greeting and a closing like a letter.', '{"question":"Which is not a part of a journal entry?","wrong_answer":"the date","correct_answer":"Yours sincerely"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "the date" next to the right answer in a new sentence and ask again.', 'A journal is not sent to anyone, so it has no closing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.JOURNAL.M_JRN_FACTS_ONLY', 'ENGL.G6.WRITIN.T12_FUNCTIONAL_WRITING.JOURNAL', 'Lists only facts and leaves out feelings.', '{"question":"What makes a journal different from a timetable?","wrong_answer":"it lists the times","correct_answer":"it tells what you felt"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "it lists the times" next to the right answer in a new sentence and ask again.', 'A journal is personal: it says how you felt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.MONEY_TRADE_WORDS.M_MON_PROFIT_LOSS', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.MONEY_TRADE_WORDS', 'Swaps profit and loss.', '{"question":"Wanjiku sold the tomatoes for less than she paid. She made a ___.","wrong_answer":"profit","correct_answer":"loss"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "profit" next to the right answer in a new sentence and ask again.', 'Profit: you get back more. Loss: you get back less.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.MONEY_TRADE_WORDS.M_MON_IMPORT_EXPORT', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.MONEY_TRADE_WORDS', 'Swaps import and export.', '{"question":"Kenya sends tea to other countries. Tea is an ___.","wrong_answer":"import","correct_answer":"export"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "import" next to the right answer in a new sentence and ask again.', 'Export: out of the country. Import: into the country.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.MONEY_TRADE_WORDS.M_MON_RETAIL_WHOLESALE', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.MONEY_TRADE_WORDS', 'Swaps retailer and wholesaler.', '{"question":"A ___ sells goods in small amounts to shoppers.","wrong_answer":"wholesaler","correct_answer":"retailer"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "wholesaler" next to the right answer in a new sentence and ask again.', 'Retailer: sells to the public in small amounts. Wholesaler: sells large amounts to shops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.DICTATION.M6_DI_SOUND_SPELLING', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.DICTATION', 'Spells words as they sound.', '{"question":"Teacher reads: \"The business was successful.\"","wrong_answer":"The bisnes was sucsesful.","correct_answer":"The business was successful."}'::jsonb, 'Phonetic spelling under time pressure.', 'Offer "The bisnes was sucsesful." beside "The business was successful." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Learn the tricky words; check after writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.DICTATION.M6_DI_MISSED_WORDS', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.DICTATION', 'Leaves out small words.', '{"question":"Teacher reads: \"She went to the market on Monday.\"","wrong_answer":"She went market Monday.","correct_answer":"She went to the market on Monday."}'::jsonb, 'Small weak words are not heard.', 'Offer "She went market Monday." beside "She went to the market on Monday." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for the little words: to, the, on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.DICTATION.M6_DI_NO_PUNCTUATION', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.DICTATION', 'Writes with no capitals or full stops.', '{"question":"Teacher reads two sentences.","wrong_answer":"one run of words","correct_answer":"two sentences, each with a capital and full stop"}'::jsonb, 'Attention goes only to the words.', 'Offer "one run of words" beside "two sentences, each with a capital and full stop" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The pause in the voice is a full stop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.DICTATION.M6_DI_ADDS_WORDS', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.DICTATION', 'Adds words that were not read.', '{"question":"Teacher reads: \"Prices went up.\"","wrong_answer":"The prices of food went up very much.","correct_answer":"Prices went up."}'::jsonb, 'The child writes what makes sense to him or her.', 'Offer "The prices of food went up very much." beside "Prices went up." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write only what you hear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.MONEY_TRADE_WORDS.M6_MON_BARTER_BUY', 'ENGL.G6.LISTEN.T13_PRONUNCIATION_AND_IN.MONEY_TRADE_WORDS', 'Thinks barter means buying with money.', '{"question":"Exchanging maize for a goat with no money is ...","wrong_answer":"buying","correct_answer":"barter"}'::jsonb, 'All trade is pictured as using money.', 'Offer "buying" beside "barter" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Barter is swapping goods without money.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T13_WORD_CLASSES.PREPOSITIONS_USE.M_PREP_BETWEEN_AMONG', 'ENGL.G6.LANGUA.T13_WORD_CLASSES.PREPOSITIONS_USE', 'Uses between for three or more, or among for two.', '{"question":"The sweets were shared ___ the five children.","wrong_answer":"between","correct_answer":"among"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "between" next to the right answer in a new sentence and ask again.', 'Between: two. Among: three or more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T13_WORD_CLASSES.PREPOSITIONS_USE.M_PREP_SINCE_FOR', 'ENGL.G6.LANGUA.T13_WORD_CLASSES.PREPOSITIONS_USE', 'Uses for with a starting point or since with a length of time.', '{"question":"We have lived here ___ 2019.","wrong_answer":"for","correct_answer":"since"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "for" next to the right answer in a new sentence and ask again.', 'Since goes with a point in time; for goes with a length of time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T13_WORD_CLASSES.PREPOSITIONS_USE.M_PREP_DEPENDENT', 'ENGL.G6.LANGUA.T13_WORD_CLASSES.PREPOSITIONS_USE', 'Uses the wrong preposition after a word (interested on, afraid from).', '{"question":"Otieno is interested ___ football.","wrong_answer":"on","correct_answer":"in"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "on" next to the right answer in a new sentence and ask again.', 'Some words take one fixed preposition: interested in, afraid of, different from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T13_WORD_CLASSES.PREPOSITIONS_USE.M_PREP_BY_WITH', 'ENGL.G6.LANGUA.T13_WORD_CLASSES.PREPOSITIONS_USE', 'Uses with for the doer or by for the tool.', '{"question":"The meat was cut ___ a knife.","wrong_answer":"by","correct_answer":"with"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "by" next to the right answer in a new sentence and ask again.', 'By tells who did it. With tells what was used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.LANGUA.T13_WORD_CLASSES.PREPOSITIONS_USE.M_PREP_DURING_FOR', 'ENGL.G6.LANGUA.T13_WORD_CLASSES.PREPOSITIONS_USE', 'Uses during for how long, or for for a named event.', '{"question":"It rained ___ the night.","wrong_answer":"for","correct_answer":"during"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "for" next to the right answer in a new sentence and ask again.', 'During goes with an event or a period (during the night). For goes with a number (for two hours).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.AFFIXES.M_AFF_WRONG_PREFIX', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.AFFIXES', 'Uses the wrong prefix for the word (dishappy, unpossible).', '{"question":"___happy","wrong_answer":"dis","correct_answer":"un"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "dis" next to the right answer in a new sentence and ask again.', 'Each prefix goes with certain words. Say the word out loud: unhappy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.AFFIXES.M_AFF_DOUBLE_LETTER', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.AFFIXES', 'Drops or adds a letter where the prefix meets the word (dissapear, mispell).', '{"question":"dis + appear","wrong_answer":"dissapear","correct_answer":"disappear"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "dissapear" next to the right answer in a new sentence and ask again.', 'Keep every letter of both parts: dis + appear = disappear; mis + spell = misspell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.AFFIXES.M_AFF_FULL', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.AFFIXES', 'Spells the suffix -ful with two l (carefull).', '{"question":"care___","wrong_answer":"full","correct_answer":"ful"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "full" next to the right answer in a new sentence and ask again.', 'The word full is not the suffix; the suffix has one l.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.AFFIXES.M_AFF_Y_TO_I', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.AFFIXES', 'Does not change y to i before a suffix (happyness).', '{"question":"happy + ness = ___","wrong_answer":"happyness","correct_answer":"happiness"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "happyness" next to the right answer in a new sentence and ask again.', 'When a word ends in consonant + y, change the y to i before the suffix.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.SPELLING_RULES.M_SP_IE_EI', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.SPELLING_RULES', 'Mixes ie and ei (recieve, beleive).', '{"question":"We ___ the parcel on Friday.","wrong_answer":"recieved","correct_answer":"received"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "recieved" next to the right answer in a new sentence and ask again.', 'I before E except after C: receive, but believe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.SPELLING_RULES.M_SP_VOWEL', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.SPELLING_RULES', 'Spells a vowel by sound (seperate, definately).', '{"question":"The twins sit at ___ desks.","wrong_answer":"seperate","correct_answer":"separate"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "seperate" next to the right answer in a new sentence and ask again.', 'Find the word hidden inside it: sep-A-rate, like a rat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.SPELLING_RULES.M_SP_SILENT', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.SPELLING_RULES', 'Leaves out a letter that is not said (goverment, enviroment).', '{"question":"We must protect the ___.","wrong_answer":"enviroment","correct_answer":"environment"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "enviroment" next to the right answer in a new sentence and ask again.', 'Say the word slowly, with every letter: environ-ment, govern-ment.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.SPELLING_RULES.M_SP_DOUBLE', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.SPELLING_RULES', 'Doubles or fails to double a letter (neccessary, tommorow, begining).', '{"question":"It is ___ to wash your hands before eating.","wrong_answer":"neccessary","correct_answer":"necessary"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "neccessary" next to the right answer in a new sentence and ask again.', 'One c, one s... n-e-c-e-ss-a-r-y: one collar, two sleeves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.SPELLING_RULES.M_SP_SOUND', 'ENGL.G6.WRITIN.T13_MECHANICS_OF_WRITING.SPELLING_RULES', 'Spells the way it is said and loses a letter (libary, Febuary).', '{"question":"Our school ___ has many books.","wrong_answer":"libary","correct_answer":"library"}'::jsonb, 'Common error of Kenyan learners of English.', 'Offer "libary" next to the right answer in a new sentence and ask again.', 'Say the r in the middle: lib-r-ary.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
